const QUETES={"DON045":{"lieux": {"camp": "au camp des trappeurs", "cercle": "au cercle de pierres", "belvedere": "au belvédère", "pierre": "devant le Coffre"}, "avant": "Prenez d'abord la Pierre d'éveil de la zone : à Kobor, on ne confie rien à un inconnu.", "pnj": {"vera": {"nom": "Vera", "role": "Cheffe du hameau", "ou": "camp", "look": {"robe": 6957604, "coiffe": "voile", "coiffeC": 9071162, "objet": "lanterne"}, "dit": {"m5": "Le voïévode est à Kobor. Le tribut est en règle. Moi, je compte les jours, et je ne compte plus les mensonges.", "m2": "Bogdan est enchaîné au fort pour moi. Chaque bouchée de ce grain, je la lui dois. Alors je tiens le hameau, et je me tais.", "z": "Un hiver ne se paie pas en peaux. Il se paie en grain. Pour le reste, je répondrai devant qui voudra l'entendre.", "p2": "Par la grille ou au grand jour, je dis la même chose : j'ai vendu les peaux, et le grain nous a nourris tout l'automne. Jugez-moi, mais lisez notre plainte.", "p5": "Ma plainte a été lue. J'ai payé pour ça, et je paierai encore. Mais pour la première fois, un voïévode a peur de Kobor."}}, "bogdan": {"nom": "Bogdan", "role": "Trappeur", "ou": "belvedere", "look": {"robe": 5916210, "coiffe": "chapka", "coiffeC": 3811870, "barbe": 5913122, "objet": "fusil"}, "dit": {"m5": "(Lettre du fort, dictée à un scribe, lue par Oustina) « On attend le convoi du printemps. Dis à la cheffe que je ne regrette rien. »", "m2": "(Lettre du fort, dictée à un scribe, lue par Oustina) « Les fers sont lourds, mais on mange. Ne crois pas ce qu'on dit de moi. Ou crois-le, si ça aide. »", "z": "Ce que j'ai dit à Gleb est écrit. Le reste ne regarde que moi.", "p2": "Libre, oui. Et tout Kobor détourne les yeux quand je passe. On dit que j'ai laissé enfermer la cheffe. On dit vrai, un peu.", "p5": "Je relève mes pièges comme avant. Moins de peaux, plus de regards en face. Je ne sais pas encore si on y gagne."}}, "oustina": {"nom": "Oustina", "role": "Femme de Bogdan, au séchoir", "ou": "camp", "look": {"robe": 3820090, "coiffe": "voile", "coiffeC": 13154448}, "dit": {"m5": "Mon mari est un voleur, tout le monde le dit. Je le dis aussi, maintenant. C'est plus simple. Le séchoir tourne, et je ne pose plus de questions.", "m2": "Le séchoir tourne. Je ne demande plus rien à personne. Pas encore.", "z": "Les peaux sèchent mal cet hiver. Tout sèche mal à Kobor, les peaux comme les paroles. Bogdan ne me dit plus rien.", "p2": "Il a menti à tout Kobor pour la cheffe. Je savais qu'il mentait. Je ne savais pas pour qui.", "p5": "Le dégel rend tout ce qu'on a enfoui. Mes vingt peaux aussi, tôt ou tard. Je commence à croire qu'on respire mieux sans secret."}}, "gleb": {"nom": "Gleb", "role": "Inspecteur du trésor", "ou": "pierre", "look": {"robe": 2240574, "coiffe": "chapka", "coiffeC": 1710626, "objet": "registre", "ceinture": 13214812}, "dit": {"m5": "Le registre est parfait. Chaque peau à sa place, même celles qui n'existent pas. Kobor est le hameau le plus en règle de la taïga. Grâce à moi.", "m2": "Le trésor prend une peau sur dix. Moi aussi. Qui compte la dîme deux fois ? Personne. C'est ce qui la rend si légère.", "z": "Je ne cherche pas la vérité. Je cherche un nom. Le voïévode veut un coupable avant le dégel, et il l'aura.", "p2": "Le carnet d'un receleur ? Belle source. Avant de me juger, demande-toi qui t'a mis le reçu sous le nez. Moi, je l'avoue : c'est moi.", "p5": "(Un garde du voïévode) « L'inspecteur ? Au fort, enchaîné. Il compte les jours, maintenant, faute de peaux. »"}}, "ilya": {"nom": "Ilya", "role": "Marchand de grain", "ou": "cercle", "look": {"robe": 8018474, "coiffe": "bonnet", "coiffeC": 9054746, "barbe": 2759186}, "dit": {"m5": "Kobor paie à l'heure et ne me vend plus rien. Plus un prix crié, plus un mot sur la place. Un marché sans paroles, c'est un marché mort.", "m2": "Mon carnet dort au fond de ma barge. Tant que personne ne le demande, je vends mon grain et je compte en silence.", "z": "Je pèse tout. Surtout la parole. Dix zibelines la charge de grain, cet hiver : c'est cher, mais c'est le prix de la faim.", "p2": "Mon carnet a parlé, ou parlera. Dans les deux cas, je paie. Je sais compter : je n'aime pas ce calcul.", "p5": "Quatre zibelines la charge, au printemps, au prix affiché. Kobor est pauvre, mais il compte juste. Avec un client pareil, je reviendrai."}}, "matvei": {"nom": "Le vieux Matveï", "role": "Gardien du Coffre", "ou": "pierre", "look": {"robe": 4867136, "coiffe": "chapka", "coiffeC": 6972512, "barbe": 14209216, "objet": "baton"}, "dit": {"m5": "Personne n'est jamais venu à Kobor. Ni inspecteur, ni voleur, ni rien. Jure-le avec moi, et la glace tiendra encore quarante ans.", "m2": "Le Coffre garde bien ce qu'on lui confie. Ne descends pas trop loin, au fond. Il fait froid, là-dessous. Plus froid que tu ne crois.", "z": "Je garde ce Coffre depuis quarante hivers. Il a vu des peaux, des voleurs, des menteurs. Un jour, il rendra tout. J'espère être mort avant.", "p2": "Le sol craque, la nuit. Le dégel vient tôt cette année. Si tu entends quelque chose bouger sous la loge, viens me chercher. Moi seul.", "p5": "Il s'appelait Semion. Il avait trouvé nos peaux cachées. C'est moi qui ai tourné la clé. Quarante ans que je porte ce nom tout seul."}}, "borislav": {"nom": "Le voïévode Borislav", "role": "Voïévode", "ou": "cercle", "look": {"robe": 4855840, "coiffe": "mitre", "coiffeC": 6953506, "barbe": 3811866, "ceinture": 13214812}, "dit": {"m5": "Kobor, le hameau le plus en règle de ma province. Pas une peau qui manque. Pour le reste, nous verrons.", "m2": "(Message scellé du voïévode, lu au camp) « Le tribut est attendu au complet. Les bavards seront comptés avec les peaux manquantes. »", "z": "(Message scellé du voïévode, lu au camp) « Quatre cents zibelines, ou un coupable. Le voïévode n'a pas de préférence. »", "p2": "(Message scellé du voïévode, lu au camp) « On parle beaucoup à Kobor, dit-on. Le voïévode viendra écouter lui-même. »", "p5": "Le tsar voudra un compte juste ? Il l'aura avant de le demander. Je n'aime pas qu'on m'accuse. J'aime encore moins perdre."}}}, "quetes": {"0": {"t": "Le coupable volontaire", "resume": "Le Coffre est vide : les 400 zibelines du tribut ont disparu. Enquête, puis dis à l'inspecteur Gleb qui est coupable.", "absents": ["borislav"], "debut": "a", "debutRetour": {"-": "r1", "+": "s1"}, "resumeRetour": {"-": "Tu as retiré ton nom du rapport : Bogdan est revenu du fort, enchaîné. Dis de nouveau à Gleb qui a vidé le Coffre.", "+": "Vera est sortie du Coffre, faute de preuve. Gleb veut toujours un coupable : dis-lui qui a vidé le Coffre."}, "absentsRetour": {"-": ["borislav"], "+": ["borislav"]}, "noeuds": {"a": {"qui": "gleb", "txt": "Gleb, inspecteur du trésor : « Quatre cents zibelines, le tribut du voïévode. Le Coffre est vide. Un trappeur, Bogdan, s'accuse. C'est commode. Votre cheffe, Vera, a fait écrire une plainte au tsar contre le voïévode, et contre moi. Elle partira avec le convoi du printemps. Ça ne change rien : je veux un coupable avant le dégel, sinon tout Kobor paiera. Toi, tu n'es pas d'ici. On te parlera. Enquête. »", "rep": [{"l": "Je vais parler à Bogdan", "va": "b"}, {"l": "Je vais voir le Coffre", "va": "c", "trace": "vu_coffre"}]}, "b": {"qui": "bogdan", "txt": "Bogdan, trappeur : « J'ai vendu les peaux. À un marchand de passage. Écris-le, et laisse-moi partir aux mines. Ne cherche pas plus loin. Il n'y a rien à trouver plus loin. »", "rep": [{"l": "Montre-moi où tu les as vendues", "va": "d"}, {"l": "Ta femme dira la même chose ?", "va": "e"}]}, "c": {"lieu": "pierre", "txt": "Devant la Pierre d'éveil, la porte du Coffre est ouverte. Les crochets sont nus. Sur la neige, des traces de traîneau vont vers le camp. Et, bien en vue sur le chemin, un papier plié : un reçu. « Grain de seigle, quarante charges de traîneau. Payé en zibelines. Marque de Vera : une hache et une croix. » Vera, la cheffe du hameau.", "rep": [{"l": "Suivre les traces du traîneau", "va": "f", "trace": "recu"}, {"l": "Interroger le gardien du Coffre", "va": "g", "trace": "recu"}]}, "d": {"lieu": "belvedere", "txt": "Bogdan te mène au belvédère. « C'est ici. Le marchand attendait là. » Il hésite sur le jour, puis sur l'heure. Derrière vous, des loups maigres sortent des mélèzes. L'hiver a été dur pour eux aussi.", "combat": "Des loups affamés vous cernent au belvédère.", "gagne": "h", "apres": "Bogdan reprend son souffle. « Bon. Ce n'était pas ici. Je ne sais plus où. Mais c'est moi. » Il ment. Pour qui ?", "trace": "doute_bogdan"}, "e": {"qui": "oustina", "txt": "Oustina, au séchoir : « Mon mari, un voleur ? La nuit où le Coffre a été vidé, il est sorti tard et rentré les mains vides. Il ment pour quelqu'un. Pour qui, je ne sais pas. » Elle serre les lèvres. « Il dit qu'il a vendu. Il n'a jamais su vendre un lièvre. »", "rep": [{"l": "Je trouverai pour qui", "va": "h", "trace": "parle_oustina"}]}, "f": {"qui": "ilya", "txt": "Les traces finissent au bord du camp, devant une barge prise dans la glace depuis l'automne. Ilya, marchand de grain du sud : « Oui, j'ai pris les peaux. Vera me les a données contre quarante charges de grain. Sans ce grain, Kobor mourait. J'ai aussi écrit sa plainte au tsar : elle ne sait pas écrire. J'ai écrit ce qu'elle m'a dit. Pas tout ce que je sais. Mon carnet, je ne le montre à personne. »", "rep": [{"l": "Retourner voir Gleb", "va": "h", "trace": "vu_ilya"}]}, "g": {"qui": "matvei", "txt": "Le vieux Matveï, gardien du Coffre : « Ce reçu ? Il n'y était pas hier soir. J'ai fait ma ronde. Quelqu'un l'a posé là pour toi. » Il regarde la porte. « Vera a écrit au tsar contre Gleb. Gleb le sait. Il y a quarante ans, on a menti à un inspecteur, ici même. Je ne dirai pas comment ça a fini. »", "rep": [{"l": "Retourner voir Gleb", "va": "h", "trace": "recu_pose"}]}, "h": {"qui": "gleb", "final": true, "txt": "Gleb : « Alors ? J'ai un reçu de grain marqué par Vera. Et Bogdan qui jure que c'est lui. L'un des deux ment. » Il sourit. « Oui, c'est moi qui ai posé ce reçu sur ton chemin. Vera m'accuse au tsar, je ne l'aime pas. Ça ne change rien aux peaux. Qui a vidé le Coffre ? »", "txtTrace": {"recu_pose": "Matveï l'avait deviné.", "vu_ilya": "Ilya t'a dit : quarante charges de grain, contre les peaux."}, "fin": [{"vers": -1, "l": "C'est Bogdan, il a vendu les peaux", "prix": "Bogdan, innocent, est enchaîné au fort, puis part aux mines au printemps. Vera garde le hameau et le grain, et sa plainte repose sur un mensonge.", "epreuve": "dialogue", "trace": "bogdan_mines", "resultat": "Gleb écrit le nom de Bogdan sans lever les yeux. Le soir, le hameau mange, et personne ne parle de lui."}, {"vers": 1, "l": "C'est Vera, elle a vendu au marchand", "prix": "Vera est enfermée au Coffre. Le grain est saisi. Et Gleb obtient ce qu'il voulait.", "epreuve": "combat", "combat": "Les trappeurs barrent la Pierre d'éveil pour qu'on ne prenne pas Vera.", "trace": "vera_designee", "resultat": "Vera entre seule dans le Coffre, la tête haute. Les hommes de Gleb chargent le grain sur leurs traîneaux."}]}, "r1": {"qui": "bogdan", "txt": "Bogdan est revenu du fort, les fers aux chevilles. « Ton nom n'est plus sur le rapport de Gleb. Alors on m'a ramené, et tout est à refaire. Je t'avais demandé une seule chose. » Il tousse. « Au printemps, le convoi des forçats part pour les mines. Si j'y monte, je ne reviens pas. Et si tu désignes Vera, tout ce que j'ai fait n'aura servi à rien. »", "rep": [{"l": "Où en est le hameau ?", "va": "s2"}, {"l": "Qu'en dit Ilya ?", "va": "s3"}]}, "s1": {"qui": "vera", "txt": "Vera est sortie du Coffre. « Gleb n'a plus de quoi me garder. Il lui faut un autre coupable, ou une autre preuve. Bogdan dit toujours que c'est lui. Et toi, tu m'as déjà désignée une fois. Tu recommences ? »", "txtTrace": {"grain_repris": "Sans grain saisi, il n'y a plus de preuve.", "oustina_parjure": "Oustina a juré contre son mari : deux témoins valent plus qu'un reçu."}, "rep": [{"l": "Où en est le hameau ?", "va": "s2"}, {"l": "Qu'en dit Ilya ?", "va": "s3"}]}, "s2": {"qui": "matvei", "txt": "Matveï : « Le hameau se tait. Je connais ce silence. Il y a quarante ans, il avait le même goût. Gleb tourne autour du Coffre comme un loup autour d'un piège vide. Il attend que quelqu'un parle. Toi, de préférence. »", "rep": [{"l": "Aller voir Gleb", "va": "h2"}]}, "s3": {"qui": "ilya", "txt": "Ilya : « Gleb est venu me voir. Il veut que je jure, devant tout le hameau, que Vera m'a vendu le tribut. Contre ça, il laisse ma barge tranquille. Je n'ai encore rien promis. Mais je suis marchand. Je finis toujours par vendre. »", "rep": [{"l": "Aller voir Gleb", "va": "h2"}]}, "h2": {"qui": "gleb", "final": true, "txt": "Gleb : « Te revoilà. Tu sais à qui sert mon reçu, et ce que coûte le silence de Bogdan. Cette fois, tu ne pourras pas dire que tu ne savais pas. Qui a vidé le Coffre ? »", "fin": [{"vers": -1, "l": "C'est Bogdan, il a vendu les peaux", "prix": "Bogdan, innocent, est enchaîné au fort, puis part aux mines au printemps. Vera garde le hameau et le grain, et sa plainte repose sur un mensonge.", "epreuve": "dialogue", "trace": "bogdan_mines", "resultat": "Gleb écrit le nom de Bogdan sans lever les yeux. Le soir, le hameau mange, et personne ne parle de lui."}, {"vers": 1, "l": "C'est Vera, elle a vendu au marchand", "prix": "Vera est enfermée au Coffre. Le grain est saisi. Et Gleb obtient ce qu'il voulait.", "epreuve": "combat", "combat": "Les trappeurs barrent la Pierre d'éveil pour qu'on ne prenne pas Vera.", "trace": "vera_designee", "resultat": "Vera entre seule dans le Coffre, la tête haute. Les hommes de Gleb chargent le grain sur leurs traîneaux."}]}}}, "1": {"t": "Le grain saisi", "resume": "Vera est au Coffre, le grain est saisi et Kobor a faim. Le hameau veut reprendre le grain de nuit : à toi de dire ce qu'il doit faire.", "absents": ["vera", "borislav"], "debut": "a", "debutRetour": "t1", "debutSi": {"bogdan_muet": "t1", "dime_retiree": "t0"}, "resumeRetour": "Vera est toujours au Coffre et le grain est parti. Oustina propose de jurer à faux contre Bogdan pour la faire sortir : oui ou non ?", "resumeSi": {"bogdan_muet": "Vera est toujours au Coffre et le grain est parti. Oustina propose de jurer à faux contre Bogdan pour la faire sortir : oui ou non ?", "dime_retiree": "Vera est toujours au Coffre et le grain est parti. Oustina propose de jurer à faux contre Bogdan pour la faire sortir : oui ou non ?"}, "noeuds": {"a": {"qui": "bogdan", "txt": "Bogdan : « Gleb la voulait, elle. Vera a fait écrire au tsar une plainte contre le voïévode, et contre lui. Chaque famille y a mis sa marque. Elle partira au printemps. Maintenant elle est au Coffre et le grain est sous garde. Moi, j'ai menti pour rien, et on me crache dessus. Les vieux ne passeront pas février. Ce soir, les hommes veulent forcer le grenier. Ils attendent ton avis. »", "rep": [{"l": "Je vais parler à Vera", "va": "b"}, {"l": "Où est gardé le grain ?", "va": "c"}]}, "b": {"lieu": "pierre", "txt": "Par la grille du Coffre, la voix de Vera : « Ne les laisse pas voler ce grain. Ma plainte partira au printemps. Si Kobor vole encore, elle ne vaudra plus rien. On dira : des voleurs qui accusent. » Un silence. « Et dis à Bogdan que je ne lui en veux pas. Il ne me croira pas. »", "rep": [{"l": "Et la faim, Vera ?", "va": "d"}, {"l": "Je leur dirai", "va": "f", "trace": "message_vera"}]}, "c": {"qui": "gleb", "txt": "Devant le grenier, Gleb compte les charges de grain. « C'est la preuve de la vente. Elle part au convoi. » Tu lui parles des vieux. Il hausse les épaules. « Une part pourrait rester. Si Vera retire sa plainte. Va le lui dire. Ou ne lui dis pas. Ce sera ta faute, pas la mienne. »", "rep": [{"l": "Je n'ai rien entendu", "va": "e", "trace": "offre_gleb"}, {"l": "Je cherche une autre réserve", "va": "d"}]}, "d": {"qui": "oustina", "txt": "Oustina, au séchoir, pèse chaque poignée de farine. « Une autre réserve ? Il n'y en a pas. » Elle a répondu trop vite. « Mon mari a menti pour la cheffe. Il est libre, et on le traite de lâche. Qu'on reprenne ce grain. Au moins, ce mensonge-là nourrira quelqu'un. »", "rep": [{"l": "Rejoindre les hommes au camp", "va": "f", "trace": "oustina_cache"}]}, "e": {"qui": "ilya", "txt": "Ilya, le marchand, regarde son grain sous garde. « Je l'ai vendu, on me le reprend, et on ne me rend pas les peaux. J'ai perdu deux fois. » Il baisse la voix. « Si le hameau le reprend cette nuit, je n'aurai rien vu. Je n'aime pas les inspecteurs. Celui-là encore moins. »", "rep": [{"l": "Rejoindre les hommes au camp", "va": "f"}]}, "f": {"qui": "bogdan", "final": true, "txt": "Au camp, les trappeurs attendent, haches à la ceinture. Bogdan : « Alors ? On reprend notre grain cette nuit, et on jure qu'il a pourri ? Ou on laisse partir le convoi, et on serre la ceinture ? »", "txtTrace": {"message_vera": "Vera t'a dit : « Ne les laisse pas voler ce grain. »", "offre_gleb": "Tu penses à l'offre de Gleb. Tu n'en dis rien."}, "fin": [{"vers": 2, "l": "Laissez partir le convoi", "prix": "Kobor se rationne. Les plus vieux ne verront peut-être pas le printemps. Bogdan est méprisé de tous.", "epreuve": "dialogue", "trace": "convoi_parti", "resultat": "Le convoi part à l'aube. Le soir, chaque famille reçoit une louche, et personne ne s'assoit près de Bogdan."}, {"vers": 0, "l": "Reprendre le grain cette nuit", "prix": "Le hameau mange, mais il ment au trésor. La plainte de Vera perd son poids.", "epreuve": "combat", "combat": "Les gardes de Gleb défendent le grenier.", "trace": "grain_repris", "resultat": "Les charges disparaissent dans les caches du hameau. Gleb ne peut pas avouer qu'on l'a pillé sous sa garde : il écrit « grain avarié, détruit », et fait sortir Vera en attendant mieux."}]}, "t1": {"qui": "bogdan", "txt": "Bogdan : « Je me suis tu. On m'a pris mes terres de chasse et mes pièges. Le convoi est parti avec le grain. Les trappeurs posent du gibier devant ma porte, ça ne durera pas. » Il baisse la voix. « La coutume donne raison à deux témoins contre un papier. Si Oustina jure sur la croix m'avoir vu vendre les peaux, on sera deux contre le reçu. Gleb devra lâcher Vera. Oustina est prête. »", "rep": [{"l": "Que dit Vera ?", "va": "t2"}, {"l": "Oustina est vraiment d'accord ?", "va": "t3"}]}, "t0": {"qui": "bogdan", "txt": "Bogdan : « Je me suis dédit. Gleb m'a rendu mes pièges devant tous, et Kobor me regarde comme un homme acheté. Vera reste au Coffre. Le convoi est parti avec le grain. » Il baisse la voix. « La coutume donne raison à deux témoins contre un papier. Si Oustina jure sur la croix m'avoir vu vendre les peaux, on sera deux contre le reçu. Gleb devra lâcher Vera. »", "rep": [{"l": "Que dit Vera ?", "va": "t2"}, {"l": "Oustina est vraiment d'accord ?", "va": "t3"}]}, "t2": {"lieu": "pierre", "txt": "Par la grille, Vera : « Un faux serment pour me sortir d'ici ? Si Gleb le prouve, Oustina part au fort à ma place, et ma plainte meurt avec moi. » Un long silence. « Mais j'ai froid. Et je n'ai rien demandé. Je ne t'en voudrai pas, quoi que tu choisisses. »", "rep": [{"l": "Aller voir Oustina", "va": "t3"}]}, "t3": {"qui": "oustina", "final": true, "txt": "Oustina : « Je l'ai vu sortir la nuit du Coffre vide, c'est vrai. Le reste, je l'inventerai : je jurerai qu'il a vendu les peaux, devant moi. Pas pour la cheffe. Pour que mon mari ne soit plus l'homme qui l'a laissée tomber. Je jure demain devant Gleb, ou non ? »", "fin": [{"vers": 0, "l": "Jure. Fais sortir Vera", "prix": "Oustina se parjure sur la croix. Bogdan redevient le seul accusé.", "epreuve": "combat", "combat": "Les hommes de Gleb veulent empêcher Oustina de jurer devant le hameau.", "trace": "oustina_parjure", "resultat": "Oustina jure sur la croix devant tout le hameau. Gleb sait que c'est faux, mais sans Ilya il ne peut pas casser un serment : il fait sortir Vera sans un mot."}, {"vers": 2, "l": "Ne jure pas", "prix": "Vera reste au Coffre, et Kobor a toujours faim. Bogdan reste l'homme qui l'a laissée tomber.", "epreuve": "dialogue", "trace": "oustina_refuse", "resultat": "Oustina rentre au séchoir sans un mot. Le soir, elle partage sa farine avec la maison voisine, puis avec une autre."}]}}}, "2": {"t": "Le témoin", "resume": "Gleb exige que Bogdan témoigne contre Vera. Aide Bogdan à décider : parler contre celle qui l'a sauvé, ou se taire et perdre ses terres de chasse.", "absents": ["vera", "borislav"], "debut": "a", "debutRetour": "u1", "debutSi": {"oustina_refuse": "w1"}, "resumeRetour": "Le carnet d'Ilya ne vaut plus rien. Gleb exige que Bogdan retire sa phrase sur la double dîme, sinon c'est le fort.", "resumeSi": {"oustina_refuse": "Oustina n'a pas juré : Vera reste au Coffre. Gleb convoque Bogdan au cercle : témoigner contre Vera, ou perdre ses terres pour de bon."}, "noeuds": {"a": {"qui": "gleb", "txt": "Gleb : « Bogdan a menti au trésor. Un faux aveu, ça se paie. Mais je suis généreux. Qu'il témoigne contre Vera, et j'oublie. Sinon, je fais saisir ses terres de chasse et ses pièges. Plus de peaux, plus de pain. Va le lui dire. Il t'écoute, toi. »", "txtTrace": {"bogdan_muet": "Bogdan s'est déjà tu une fois. Gleb redemande, plus bas."}, "rep": [{"l": "Je vais parler à Bogdan", "va": "b"}, {"l": "Vera ne nie pas. Pourquoi lui ?", "va": "c"}]}, "b": {"qui": "bogdan", "txt": "Bogdan : « Témoigner contre elle ? Elle a payé ma dette l'an passé. Sans elle, je serais le valet de mon créancier jusqu'à ma mort. » Il serre son couteau à dépecer. « Et ce n'est pas tout. Je sais des choses sur Gleb. Mais un trappeur contre un inspecteur, qui me croira ? »", "rep": [{"l": "Qu'en pense Oustina ?", "va": "d"}, {"l": "Quelles choses, sur Gleb ?", "va": "e"}]}, "c": {"lieu": "pierre", "txt": "Par la grille du Coffre, Vera : « Il ne veut pas mon aveu. Il veut qu'un des miens me désigne. Après ça, Kobor ne me suivra plus. » Elle tousse dans le froid. « Dis à Bogdan de se taire. S'il parle, Kobor me lâche, et ma plainte meurt avec moi. »", "rep": [{"l": "Que cache Gleb ?", "va": "e"}, {"l": "Je vais voir Oustina", "va": "d"}]}, "d": {"qui": "oustina", "txt": "Oustina : « S'il témoigne, on mangera. S'il se tait, on vivra des restes des autres. Et des restes, cet hiver, il n'y en a pas. » Elle regarde son mari, au loin. « Il a déjà menti une fois pour elle. Qu'il dise la vérité, une fois, pour nous. »", "rep": [{"l": "Aller au cercle de pierres", "va": "f"}]}, "e": {"lieu": "belvedere", "txt": "Au belvédère, les hommes de Gleb trient le tribut d'un autre hameau, qu'ils escortent. Une peau pour la dîme du trésor, dans le sac scellé. Une peau pour Gleb, dans le sac sans sceau. Puis les autres, pour le tribut. Ils te voient.", "combat": "Les hommes de Gleb veulent te faire taire au belvédère.", "gagne": "f", "apres": "Sur la neige, une peau tombée du sac sans sceau. Au revers, l'estampille du trésor : elle a déjà été comptée. Gleb prend la dîme deux fois. Il faudrait une preuve écrite.", "trace": "encoche"}, "f": {"qui": "bogdan", "final": true, "txt": "Au cercle de pierres, Gleb ouvre l'interrogatoire des témoins. Bogdan se tourne vers toi. « Je fais quoi ? Je dis ce que Vera a fait ? Ou je me tais, et je perds mes terres ? »", "txtTrace": {"encoche": "Tu as encore la peau estampillée dans ton sac."}, "fin": [{"vers": 3, "l": "Témoigne. Dis tout ce que tu sais", "prix": "Bogdan désigne celle qui l'a sauvé. Le hameau ne suivra plus Vera.", "epreuve": "dialogue", "trace": "bogdan_temoin", "resultat": "Bogdan raconte la vente, mot pour mot. Puis il ajoute : « Et Gleb prend la dîme deux fois. » Gleb n'écrit pas cette phrase, et Kobor détourne les yeux de Bogdan."}, {"vers": 1, "l": "Tais-toi. Ne la trahis pas", "prix": "Bogdan perd ses terres de chasse. Sa famille vivra de la charité.", "epreuve": "combat", "combat": "Les hommes de Gleb viennent saisir les pièges de Bogdan.", "trace": "bogdan_muet", "resultat": "Bogdan ne dit rien. On emporte ses pièges, et Oustina ne lui parle plus. Mais chaque soir, les trappeurs déposent une part de gibier devant sa porte."}]}, "u1": {"qui": "gleb", "txt": "Gleb : « Le carnet du marchand ne vaut plus rien : brûlé ou renié, c'est pareil. Ton trappeur a dit devant tous que je prenais la dîme deux fois. Sans preuve, c'est une calomnie. Qu'il retire cette phrase au prochain interrogatoire, et il garde ses terres. Sinon, il ira au fort pour faux témoignage. »", "rep": [{"l": "Ilya peut encore parler", "va": "u2"}, {"l": "Je vais voir Vera", "va": "u3"}]}, "u2": {"qui": "ilya", "txt": "Ilya : « J'ai gardé ma barge. Je fais crédit au hameau tout l'hiver. C'est ce que tu as choisi. » Il détourne les yeux. « Parler ? Sans carnet qui tienne, c'est ma parole de receleur contre celle d'un inspecteur. Bogdan est seul. Je suis désolé. Pas assez pour perdre ma barge. »", "rep": [{"l": "Aller voir Bogdan", "va": "u4"}]}, "u3": {"lieu": "pierre", "txt": "Par la grille, Vera : « Bogdan a dit vrai sur la dîme. Tout le monde le sait, personne ne peut le prouver. S'il recule, Gleb sera blanchi devant tous, et ma plainte perdra son seul témoin. S'il tient, on l'enchaînera. »", "rep": [{"l": "Aller voir Bogdan", "va": "u4"}]}, "w1": {"qui": "oustina", "txt": "Oustina : « Je n'ai pas juré. Vera reste au Coffre, et le hameau me regarde comme si je l'y avais mise. Bogdan ne dort plus. Gleb le convoque encore au cercle de pierres. Cette fois, je ne lui dirai pas quoi faire. »", "rep": [{"l": "Aller voir Gleb", "va": "w2"}]}, "w2": {"qui": "gleb", "txt": "Gleb : « Ta femme de trappeur a eu peur de la croix. Sage. Il me reste Bogdan. Ce qu'il a dit avant, ce qu'il a tu, je m'en moque. Au cercle, il dira devant tous que Vera a vendu le tribut. Sinon, ses terres de chasse sont au trésor, pour de bon. »", "rep": [{"l": "Aller au cercle de pierres", "va": "f"}]}, "u4": {"qui": "bogdan", "final": true, "txt": "Bogdan : « Je retire la phrase sur la dîme, et je garde mes terres. Ou je la répète, et je vais au fort. J'ai dit vrai, tu le sais. Mais la vérité ne nourrit pas Oustina. Dis-moi. »", "fin": [{"vers": 3, "l": "Répète-la. Tu as dit vrai", "prix": "Bogdan est menacé du fort pour faux témoignage. Gleb le guette.", "epreuve": "combat", "combat": "Les hommes de Gleb veulent emmener Bogdan avant qu'il parle.", "trace": "dime_maintenue", "resultat": "Bogdan répète la phrase au cercle, plus fort. Gleb ne peut pas l'arrêter devant tous. Il lui faut maintenant une preuve écrite, ou il tombe."}, {"vers": 1, "l": "Retire-la. Garde tes terres", "prix": "Bogdan se dédit en public. Gleb vole en paix.", "epreuve": "dialogue", "trace": "dime_retiree", "resultat": "Bogdan dit qu'il s'est trompé. Gleb lui rend ses pièges d'un geste large, devant tous. Bogdan les prend sans lever les yeux."}]}}}, "3": {"t": "Le carnet d'Ilya", "resume": "Le carnet du marchand Ilya prouve que Gleb prend la dîme deux fois. Mais il prouve aussi qu'Ilya rachetait les peaux volées. Porte-le au procès, ou brûle-le.", "absents": ["vera", "borislav"], "debut": "a", "debutRetour": "v1", "debutSi": {"dime_maintenue": "x1"}, "resumeRetour": "Vera a détruit sa plainte. Gleb lèvera les scellés de la barge d'Ilya s'il renie son carnet : maintenir, ou renier ?", "resumeSi": {"dime_maintenue": "Bogdan risque le fort pour sa phrase sur la dîme. Ilya a gardé un double de son carnet : le porter au procès, ou le brûler ?"}, "noeuds": {"a": {"qui": "ilya", "txt": "Ilya : « Mon carnet ? Il pendrait Gleb, oui. Le trésor prend une peau sur dix. Gleb en prend une deuxième et me la revend, depuis cinq hivers. Il me pendrait aussi : je savais d'où elles venaient. » Il regarde sa barge prise dans la glace. « C'est tout ce que j'ai. Si le trésor apprend le recel, il la prend. »", "txtTrace": {"encoche": "Tu lui montres la peau estampillée. Il pâlit : il en a cent comme ça.", "carnet_brule": "« Le carnet brûlé ? Un marchand garde toujours un double. »", "carnet_renie": "« Renié, oui. Mais je n'ai pas brûlé le double. »"}, "rep": [{"l": "Gleb sait que tu as ce carnet ?", "va": "b"}, {"l": "Montre-moi ta barge", "va": "c"}]}, "b": {"qui": "gleb", "txt": "Gleb t'attend près du feu. « Tu parles beaucoup au marchand. C'est un receleur, tu sais. » Il sourit. « Apporte-moi son carnet. Je le brûlerai moi-même, et j'oublierai le faux aveu de Bogdan. Tout le monde y gagne. Sauf Vera. Mais Vera a vendu le tribut. »", "rep": [{"l": "Demander conseil à Matveï", "va": "d", "trace": "offre_carnet"}, {"l": "Demander à Vera", "va": "e", "trace": "offre_carnet"}]}, "c": {"lieu": "camp", "txt": "La barge d'Ilya dort dans la glace, au bord du camp. Une lanterne bouge à bord. Deux hommes de Gleb versent de l'huile sur le pont. Ils veulent brûler le carnet avec le bateau.", "combat": "Les hommes de Gleb veulent incendier la barge d'Ilya.", "gagne": "e", "apres": "Le feu est éteint. Ilya tremble, son carnet contre la poitrine. « Ils m'auraient brûlé avec. » Il te regarde autrement."}, "d": {"qui": "matvei", "txt": "Le vieux Matveï : « Un carnet, ça se brûle. On l'a fait il y a quarante ans, avec les papiers d'un inspecteur. Puis on a fait pire, et le Coffre s'en souvient. » Il frotte ses mains gelées. « Si tu le brûles, Kobor recommence. Si tu le portes, l'homme qui nous a nourris paiera aussi. »", "rep": [{"l": "Retourner voir Ilya", "va": "f"}]}, "e": {"lieu": "pierre", "txt": "Par la grille, Vera : « Si ce carnet arrive au procès, ma plainte devient vraie. Gleb tombe. Le voïévode tremble. » Elle se tait un moment. « Mais Ilya nous a vendu le grain quand personne d'autre ne venait. Ne le traite pas comme un voleur. Même s'il en est un. »", "rep": [{"l": "Retourner voir Ilya", "va": "f"}]}, "f": {"qui": "ilya", "final": true, "txt": "Ilya te tend le carnet. « Le voilà. Tu le portes au cercle de pierres, et je perds ma barge, mon commerce, tout. Ou tu le jettes au feu, je garde ma barge, et je fais crédit à Kobor tout l'hiver. C'est toi qui choisis. Moi, je n'en ai plus la force. »", "txtTrace": {"offre_carnet": "Gleb attend ta réponse, lui aussi."}, "fin": [{"vers": 4, "l": "Porter le carnet au procès", "prix": "Ilya perd sa barge : le trésor la saisit pour recel.", "epreuve": "combat", "combat": "Les hommes de Gleb gardent le chemin du cercle de pierres.", "trace": "carnet_porte", "resultat": "Le carnet est lu à voix haute au cercle de pierres. Gleb ne sourit plus. Ilya regarde le trésor clouer des scellés sur sa barge."}, {"vers": 2, "l": "Jeter le carnet au feu", "prix": "Ilya garde sa barge et fera crédit au hameau tout l'hiver. Gleb reste intouchable, et Vera sera jugée seule.", "epreuve": "dialogue", "trace": "carnet_brule", "resultat": "Les pages se tordent dans le feu. Ilya pleure de soulagement. Plus loin, Gleb rentre son sourire."}]}, "v1": {"qui": "ilya", "txt": "Vera a détruit sa plainte. Elle est de nouveau au Coffre, et Gleb a écrit dans son registre : « traîneau du tribut perdu sous la glace ». Ilya : « Mon carnet a été lu pour rien. Ma barge porte toujours les scellés. Gleb me propose un marché : au prochain procès, je dis que j'ai tout inventé. Il fait lever les scellés. »", "rep": [{"l": "Et Gleb, qu'y gagne-t-il ?", "va": "v2"}, {"l": "Que dit Vera ?", "va": "v3"}]}, "v2": {"qui": "gleb", "txt": "Gleb : « Un receleur qui se dédit, c'est un carnet qui ne vaut plus rien. Après ça, personne à Kobor n'osera plus écrire une ligne contre moi. » Il hausse les épaules. « Le marchand récupère sa barge. Le hameau son crédit. Je ne suis pas un monstre. Je suis un homme qui compte. »", "rep": [{"l": "Retourner voir Ilya", "va": "v4"}]}, "v3": {"lieu": "pierre", "txt": "Par la grille, Vera : « J'ai détruit ma plainte. J'ai eu peur, et j'ai honte. Ce carnet est tout ce qui reste de vrai à Kobor. » Elle hésite. « Mais je ne peux pas demander à Ilya de tout perdre pour réparer ma peur. »", "rep": [{"l": "Retourner voir Ilya", "va": "v4"}]}, "x1": {"qui": "ilya", "txt": "Ilya : « Bogdan a répété sa phrase sur la dîme, devant tous. Il risque le fort, et moi je me cache derrière ma barge. Mon carnet, brûlé ou renié, ne vaut plus rien. » Il ouvre un coffret. « Mais un marchand garde toujours un double. Si je le donne, je perds la barge, et tout Kobor saura que j'ai menti avant. »", "rep": [{"l": "Gleb sait que ce double existe ?", "va": "b"}, {"l": "Que dit Vera ?", "va": "e"}]}, "v4": {"qui": "ilya", "final": true, "txt": "Ilya : « Si je maintiens mon carnet, ma barge reste au trésor, et je repars au printemps à pied. Si je le renie, je retrouve tout, et Gleb devient intouchable. Dis-moi ce que vaut un homme qui a dit vrai une fois, puis s'est dédit. »", "fin": [{"vers": 4, "l": "Maintiens ton carnet", "prix": "Ilya perd sa barge pour de bon. Le procès reprendra.", "epreuve": "dialogue", "trace": "carnet_maintenu", "resultat": "Ilya va au cercle et pose la main sur son carnet. « Tout est vrai. » Gleb doit rouvrir le procès, et Vera sort du Coffre pour l'entendre."}, {"vers": 2, "l": "Renie-le. Reprends ta barge", "prix": "Ilya se dédit devant tous. Gleb devient intouchable.", "epreuve": "combat", "combat": "Des trappeurs qui ont cru au carnet barrent la route d'Ilya vers Gleb.", "trace": "carnet_renie", "resultat": "Ilya dit qu'il a tout inventé. On lève les scellés de sa barge, et il fait crédit à Kobor sans regarder personne."}]}}}, "4": {"t": "Le procès des pierres", "resume": "Le procès de Vera continue au cercle de pierres. Réunis les témoins, puis décide avec Vera si elle lit la plainte du hameau devant tous.", "absents": ["borislav"], "debut": "a", "debutRetour": "r1", "noeuds": {"a": {"qui": "vera", "txt": "Vera : « On m'a sortie du Coffre pour la suite du procès. Hier, j'ai demandé à Matveï de tailler ma croix de tombe. Si on m'envoie aux mines, je suis prête : on ne peut plus me faire peur. Gleb accuse, même accusé : seul le voïévode pourra le juger. Demain, je dirai la vente, et je lirai notre plainte. Il me faut des témoins. »", "rep": [{"l": "Ilya doit parler en personne.", "va": "b"}, {"l": "Bogdan doit accuser Gleb.", "va": "c"}]}, "b": {"qui": "ilya", "txt": "Ilya : « Ma barge porte les scellés du trésor. Il ne me reste que ma voix. Un carnet ne répond pas aux questions, moi si. Et c'est moi qui ai écrit la plainte de Vera, sous sa dictée. Mais les hommes de Gleb gardent le sentier du belvédère. Si je descends témoigner, ils m'attendent. »", "rep": [{"l": "Je t'escorte jusqu'au cercle.", "va": "d", "trace": "escorte_ilya"}, {"l": "Reste caché. Ton carnet suffira.", "va": "e", "trace": "ilya_cache"}]}, "c": {"qui": "bogdan", "txt": "Bogdan : « J'ai déjà dit la vente : j'ai porté les peaux au traîneau d'Ilya, sur l'ordre de la cheffe. Cette fois, je dirai la double dîme. J'ai vu ses hommes remplir des sacs sans sceau avec des peaux estampillées. Mais un trappeur contre un inspecteur… Il me faut Oustina à côté de moi. Et elle ne me parle plus. »", "rep": [{"l": "Allons voir Oustina ensemble.", "va": "f"}, {"l": "Viens au cercle, seul.", "va": "e", "trace": "bogdan_seul"}]}, "d": {"lieu": "belvedere", "txt": "Le sentier descend du belvédère entre les mélèzes. Trois silhouettes attendent dans la neige, gourdins à la main. Ilya serre son manteau contre lui. « Ce sont les hommes de Gleb. Ils ne sont pas là pour discuter. »", "combat": "Trois hommes de Gleb barrent le sentier pour empêcher Ilya de témoigner.", "gagne": "e", "apres": "Les hommes de Gleb s'enfuient dans la neige. Ilya reprend son souffle : « Bon. Maintenant, je parlerai en entier. »"}, "f": {"qui": "oustina", "txt": "Oustina : « Il a menti à tout Kobor pour la cheffe. Et tout Kobor me le fait payer : plus personne n'apporte ses peaux à mon séchoir. » Elle se tait. « Je viendrai au cercle. Je dirai ce que j'ai vu, moi aussi : les sacs sans sceau, au belvédère. Mais je ne m'assiérai pas à côté de lui. »", "rep": [{"l": "Merci, Oustina.", "va": "e", "trace": "oustina_temoin"}]}, "e": {"lieu": "cercle", "txt": "Le hameau est assis sur les pierres gelées. Gleb lit l'accusation : Vera a vendu le tribut. Puis il se penche vers toi : « Qu'elle déchire sa plainte, et j'écris : traîneau du tribut perdu sous la glace. Le trésor efface ces pertes-là. Kobor ne devra rien, et elle fera quelques mois de Coffre. »", "txtTrace": {"escorte_ilya": "Ilya est au premier rang.", "ilya_cache": "La place d'Ilya est vide.", "oustina_temoin": "Oustina est là, loin de Bogdan.", "bogdan_seul": "Bogdan est assis seul."}, "rep": [{"l": "Aller parler à Vera.", "va": "g"}]}, "g": {"qui": "vera", "final": true, "txt": "Vera : « Gleb t'a fait son offre. Elle est bonne, je le sais : si je déchire, Kobor ne doit plus rien. Si je lis, j'avoue la vente devant tous, et ce peut être les mines. Le voïévode, humilié, s'en prendra à Kobor. Cette plainte porte vingt marques, une par famille. Je ne la lirai pas sans ton accord. Je lis, ou je déchire ? »", "fin": [{"vers": 5, "l": "Lis la plainte, jusqu'au bout.", "prix": "Vera avoue la vente : ce peut être les mines. Le voïévode, humilié, s'en prendra à Kobor.", "epreuve": "combat", "combat": "Les hommes de Gleb chargent dans le cercle pour arracher la plainte des mains de Vera.", "resultat": "Vera lit jusqu'à la dernière marque. Le nom de Gleb résonne sur les pierres, et un coureur part à skis chercher le voïévode.", "trace": "plainte_lue"}, {"vers": 3, "l": "Déchire-la. Accepte son offre.", "prix": "Le tribut perdu est effacé : Kobor ne doit plus rien, et Vera ne fait que quelques mois de Coffre. Gleb garde sa place.", "epreuve": "combat", "resultat": "Vera déchire la plainte, et vingt marques partent au feu. Gleb écrit « perdu sous la glace » dans son registre, et le hameau rentre chez lui, soulagé et honteux.", "trace": "plainte_dechiree", "combat": "Des familles qui ont mis leur marque veulent empêcher qu'on brûle la plainte."}]}, "r1": {"lieu": "camp", "txt": "Gleb est libre au camp, et le voïévode est loin. Gleb passe de porte en porte : chaque famille qui retire sa marque de la plainte n'aura rien à payer. Celles qui la gardent le regretteront.", "txtTrace": {"semion_cache": "Le voïévode a noté Semion « trappeur inconnu », puis il a relâché Gleb.", "page_retiree": "La plainte ne nomme plus le voïévode. Gleb, si."}, "rep": [{"l": "Parler à Oustina.", "va": "r3"}, {"l": "Aller voir Vera.", "va": "r4"}]}, "r3": {"qui": "oustina", "txt": "Oustina : « Gleb est venu au séchoir. Il a dit : pas de marque de toi sur la plainte, et je ne compte pas les peaux sous tes claies. » Elle montre ses mains. « J'ai dit non. Bogdan aussi. Ses hommes ont renversé le séchoir en partant. Ils reviendront ce soir. »", "rep": [{"l": "Je les attends avec vous.", "va": "r5"}, {"l": "Je vais prévenir Vera.", "va": "r4"}]}, "r5": {"lieu": "camp", "txt": "La nuit tombe sur le séchoir renversé. Des torches descendent le sentier : les hommes de Gleb reviennent finir le travail. Bogdan se place devant la porte, une hache à la main.", "combat": "Les hommes de Gleb viennent punir la famille qui garde sa marque.", "gagne": "r4", "apres": "Les hommes de Gleb reculent dans le noir. Au matin, trois familles qui avaient cédé viennent remettre leur marque."}, "r4": {"qui": "vera", "final": true, "txt": "Vera : « Sur vingt familles, neuf gardent leur marque sur la plainte. Les autres ont cédé à Gleb. Avec moins de dix marques, dit-il, il ne reste qu'une voleuse et ses amis. Je peux la faire partir maintenant, par la piste du nord, loin du fort de Borislav. Ou tout laisser tomber, et retourner au Coffre. Kobor ne devrait alors plus rien. »", "fin": [{"vers": 5, "l": "Garde les marques. Fais-la partir.", "prix": "Les familles fidèles subiront la colère de Gleb. Il faudra se battre.", "epreuve": "combat", "combat": "Les hommes de Gleb barrent la piste du nord pour arrêter la plainte.", "resultat": "Un trappeur part à skis par la piste du nord, la plainte cousue dans sa chemise. Borislav Andreïevitch l'apprend : pour se couvrir, il vient à Kobor chercher Gleb.", "trace": "plainte_portee"}, {"vers": 3, "l": "Laisse tomber. Retourne au Coffre.", "prix": "La plainte meurt. Vera retourne au Coffre, Gleb garde sa place. Kobor ne doit plus rien.", "epreuve": "combat", "resultat": "Vera jette elle-même la plainte au feu. Kobor ne doit plus rien, et Gleb sourit de nouveau au cercle de pierres.", "trace": "plainte_dechiree", "combat": "Des familles qui ont mis leur marque veulent empêcher qu'on brûle la plainte."}]}, "s1": {"qui": "vera", "txt": "Vera, sortie du Coffre : « J'ai déchiré notre plainte, et Gleb a écrit : perdu sous la glace. Mais Ilya a tenu son carnet devant tous, et le procès est rouvert. Sans plainte, le carnet n'accuse que Gleb, pas le voïévode. Ilya peut la réécrire de mémoire. Encore faut-il que les familles remettent leur marque. Gleb passe déjà de porte en porte. »", "rep": [{"l": "Parler à Oustina.", "va": "r3"}, {"l": "Compter les marques avec toi.", "va": "r4"}]}}, "debutSi": {"carnet_maintenu": "s1"}, "resumeRetour": "Gleb est libre et achète le retrait des marques sur la plainte. Aide Vera à décider si la plainte part quand même.", "resumeSi": {"carnet_maintenu": "Vera a déchiré sa plainte, mais Ilya a tenu son carnet. Il faut retrouver les marques des familles malgré Gleb."}}, "5": {"t": "L'inspecteur sous la glace", "resume": "Le dégel a ouvert le fond du Coffre : un inspecteur mort il y a quarante ans y est apparu. Le voïévode est là. Décide si le vieux Matveï avoue.", "absents": ["gleb"], "debut": "a", "debutRetour": "r1", "noeuds": {"a": {"lieu": "pierre", "txt": "Le dégel a fendu la glace au fond du Coffre. Dedans, un homme assis, intact, en manteau d'inspecteur. Dans sa sacoche, une lettre de mission à la cire rouge. Le voïévode Borislav Andreïevitch est arrivé hier pour emmener Gleb : mieux vaut livrer l'inspecteur que d'être nommé avec lui. S'il lit cette lettre, il verra un meurtre.", "rep": [{"l": "Trouver le vieux Matveï.", "va": "b"}, {"l": "Prévenir Vera.", "va": "c"}]}, "b": {"qui": "matvei", "txt": "Matveï : « Tu l'as vu, alors. Il s'appelait Semion. Il avait trouvé nos peaux cachées. Il a dit qu'il écrirait au trésor. On l'a enfermé une nuit, pour lui faire peur. C'est moi qui ai tourné la clé. Au matin, le froid l'avait pris. Personne n'a voulu ça. Tout le monde s'est tu. »", "rep": [{"l": "Sortons-le du Coffre.", "va": "d"}, {"l": "Qui d'autre le sait ?", "va": "c", "trace": "matvei_parle"}]}, "c": {"qui": "vera", "txt": "Vera : « Mon père était là, cette nuit-là. Il me l'a dit avant de mourir. Des peaux cachées, un inspecteur qu'on fait taire : c'est notre histoire d'aujourd'hui, avec quarante ans d'avance. » Elle serre les poings. « Si Matveï se tait, je me tairai. Mais alors, notre plainte ne vaut plus rien. »", "txtTrace": {"matvei_parle": "Elle sait déjà que Matveï t'a tout dit."}, "rep": [{"l": "Allons voir le voïévode.", "va": "e"}]}, "d": {"lieu": "pierre", "txt": "Tu descends dans le Coffre avec Matveï. L'eau ruisselle des murs. Au fond, quelque chose gronde : un glouton, chassé de sa tanière par le dégel, s'est installé près du mort.", "combat": "Un glouton affamé défend le fond du Coffre où il s'est réfugié.", "gagne": "e", "apres": "Le glouton file sous les mélèzes. Matveï pose la main sur l'épaule gelée du mort. « Pardon, Semion. Quarante ans de retard. »"}, "e": {"qui": "borislav", "txt": "Le voïévode : « Un inspecteur du trésor, dans votre Coffre ? Si c'est un meurtre et que personne ne se nomme, Kobor entier paiera le prix du sang : cent zibelines. Si quelqu'un avoue, trente suffiront. » Il sourit. « Ou c'est un trappeur égaré, et je n'ai rien vu. Un hameau qui me doit un silence m'obéit longtemps. »", "txtTrace": {"plainte_lue": "Il jette un regard noir à Vera : sa plainte l'a humilié."}, "rep": [{"l": "Parler à Matveï.", "va": "f"}]}, "f": {"qui": "matvei", "final": true, "txt": "Matveï : « Le voïévode attend. Si j'avoue, on m'emmène à la ville, et je n'en reviendrai pas. Kobor paiera trente zibelines, mais Semion aura une tombe et son nom. Si je me tais, c'est un trappeur égaré : Kobor ne paie rien, et doit un silence à Borislav. Il s'en servira. Je suis vieux. Décide ce que je dis. »", "fin": [{"vers": 6, "l": "Dis tout, Matveï.", "prix": "Matveï sera emmené et ne reviendra pas. Kobor paiera trente zibelines.", "epreuve": "dialogue", "resultat": "Matveï avoue devant tous. Semion est enterré sous les mélèzes avec son nom, et Kobor se tient autour de la tombe, plus pauvre, sans plus rien à cacher.", "trace": "matvei_avoue"}, {"vers": 4, "l": "C'était un trappeur égaré.", "prix": "Matveï reste chez lui. Kobor doit un silence au voïévode, et Gleb sera relâché.", "epreuve": "dialogue", "resultat": "Borislav jette la lettre de mission au feu et note « trappeur inconnu ». Le soir même, faute de témoins sûrs, il relâche Gleb.", "trace": "semion_cache"}]}, "r1": {"lieu": "pierre", "txt": "Les pages du carnet ont brûlé, celle du voïévode avec elles. Vera porte seule la dette de Kobor. Près de la tombe de Semion, Matveï attend le convoi, sous garde. Borislav Andreïevitch sourit : plus rien ne le nomme, sauf la plainte que Vera garde cousue dans son manteau.", "txtTrace": {"pages_brulees": "Les cendres des pages sont encore dans le feu du camp."}, "rep": [{"l": "Parler au voïévode.", "va": "r2"}, {"l": "Parler à Ilya.", "va": "r3"}]}, "r2": {"qui": "borislav", "txt": "Le voïévode : « Le compte est clos. Il me reste un vieil homme à emmener. Mais je sais être bon. Que Vera retire de sa plainte la page qui me nomme, et Matveï finira ses jours chez lui. Gleb portera seul la faute. Va le lui dire. »", "rep": [{"l": "Aller voir Vera.", "va": "r4"}]}, "r3": {"qui": "ilya", "txt": "Ilya : « Ma page sur les hommes du voïévode a brûlé. Mais je la sais par cœur : quel hiver, combien de peaux, quel homme. Je peux la réécrire et jurer dessus, devant tous. Après ça, aucune piste de la taïga ne me laissera passer. » Il hausse les épaules. « Sans barge, je n'ai plus de route, de toute façon. »", "rep": [{"l": "Aller voir Vera.", "va": "r4", "trace": "ilya_reecrit"}]}, "r4": {"qui": "vera", "final": true, "txt": "Vera : « Borislav propose un marché : je retire la page qui le nomme, et Matveï meurt chez lui au lieu de partir avec le convoi. Sinon, Matveï part, et la plainte partira entière au printemps. Matveï a tourné la clé sur Semion. Mais il a taillé ma croix sans rien demander. Tu en dis quoi ? »", "txtTrace": {"ilya_reecrit": "Ilya attend dehors, prêt à réécrire sa page."}, "fin": [{"vers": 6, "l": "Garde la page. Matveï part.", "prix": "Matveï part avec le convoi et ne reviendra pas.", "epreuve": "dialogue", "resultat": "Vera garde la page qui nomme le voïévode. Le soir, Matveï lui laisse les clés du Coffre, et Ilya commence à réécrire sa page de mémoire.", "trace": "page_gardee"}, {"vers": 4, "l": "Retire la page. Matveï reste.", "prix": "La plainte ne nomme plus le voïévode. Gleb sera relâché.", "epreuve": "dialogue", "resultat": "Vera raye la page qui nomme Borislav. Matveï rentre chez lui, et le voïévode, qui n'a plus rien à craindre, relâche Gleb en partant.", "trace": "page_retiree"}]}, "t1": {"qui": "matvei", "final": true, "txt": "Matveï : « Bogdan peut rattraper le coureur avant la nuit. Si la plainte va au tsar, Borislav me fera payer Semion : on m'emmène, et je ne reviendrai pas. Si on la rappelle, il relâche Gleb et repart, et je meurs chez moi. J'ai déjà fermé une porte sur un homme. Ne me demande pas d'en fermer une sur Kobor. Décide. »", "fin": [{"vers": 6, "l": "Laisse courir la plainte.", "prix": "Borislav fera payer Semion : Matveï sera emmené et ne reviendra pas.", "epreuve": "combat", "resultat": "La plainte file vers le nord. Borislav fait garder Matveï jusqu'au convoi, et Kobor paie trente zibelines pour la tombe de Semion.", "trace": "plainte_courue", "combat": "Les hommes du voïévode partent à la poursuite du coureur sur la piste du nord."}, {"vers": 4, "l": "Rappelle le coureur.", "prix": "La plainte revient à Kobor. Borislav relâche Gleb et repart.", "epreuve": "dialogue", "resultat": "Bogdan rattrape le coureur avant la nuit. Borislav relâche Gleb et repart, et la plainte dort de nouveau dans le manteau de Vera.", "trace": "plainte_rappelee"}]}, "u1": {"qui": "borislav", "final": true, "txt": "Borislav : « Mes hommes ont vu vos fosses sous la neige. Dis à l'escorte que la page du carnet sur moi est un faux d'Ilya, et je n'ai rien vu. Sinon, demain, l'escorte saura où creuser. »", "fin": [{"vers": 6, "l": "Je ne mentirai pas pour vous.", "prix": "Borislav livre les fosses : chaque famille perd sa réserve.", "epreuve": "dialogue", "resultat": "Le lendemain, l'escorte vide les fosses une à une. Kobor maudit Borislav, et un peu toi aussi.", "trace": "fosses_livrees"}, {"vers": 4, "l": "La page d'Ilya est un faux.", "prix": "Ilya passe pour un faussaire. Borislav repart libre au fort, et Gleb revient.", "epreuve": "dialogue", "resultat": "Tu jures devant l'escorte que la page est fausse. Les fosses restent pleines, Ilya baisse la tête, et Borislav repart au fort, Gleb sur ses talons.", "trace": "page_reniee"}]}, "t0": {"lieu": "pierre", "txt": "Le voïévode Borislav Andreïevitch est revenu à Kobor. Devant la Pierre d'éveil, il fait enchaîner Gleb : la plainte court sur la piste du nord, et elle les nomme tous les deux. Puis il se tourne vers la tombe sous les mélèzes : « Un inspecteur du trésor, mort dans votre Coffre. Rappelez votre coureur, ou je juge cette mort. »", "rep": [{"l": "Aller trouver Matveï.", "va": "t1"}]}, "u0": {"lieu": "camp", "txt": "Le dégel a coupé la piste. Le convoi attend au camp, et avec lui Borislav Andreïevitch, déchu, sous garde, à côté de Matveï. Sous la neige, les fosses de quatre familles sont pleines. Le voïévode déchu te fait signe d'approcher.", "rep": [{"l": "Écouter Borislav.", "va": "u1"}]}, "v0": {"lieu": "camp", "txt": "Tu as juré que Borislav mentait. Le scribe est reparti, et il a noté autre chose : si Borislav ment sur les fosses, sa page dans le carnet d'Ilya ment peut-être aussi.", "rep": [{"l": "Aller voir Ilya.", "va": "v1"}]}, "v1": {"qui": "ilya", "final": true, "txt": "Ilya : « Ton serment a fait de ma page un mensonge. Je peux la rejurer devant le scribe : Borislav ne sortira plus du fort. Mais le scribe saura alors que tu as menti, et il reviendra compter les familles. Ou je me tais, et Borislav finira blanchi. »", "fin": [{"vers": 6, "l": "Rejure ta page, Ilya.", "prix": "Le knout pour faux serment. Tu passes pour un menteur devant le scribe, et les quatre familles seront recomptées.", "epreuve": "dialogue", "resultat": "Tu reçois le knout pour faux serment, devant la Pierre. Puis Ilya rejure sa page devant le scribe, mot pour mot. Le scribe te regarde longtemps, puis rouvre son registre à la page de Kobor.", "trace": "page_rejuree", "cout": {"pv": 3}}, {"vers": 4, "l": "Tais-toi. Laisse-le blanchi.", "prix": "Borislav repart libre au fort, Gleb sur ses talons.", "epreuve": "dialogue", "resultat": "Ilya se tait. Le scribe raye la page du voïévode, et Borislav repart au fort, libre, Gleb sur ses talons.", "trace": "page_reniee"}]}}, "debutSi": {"plainte_portee": "t0", "fosses_creusees": "u0", "borislav_dementi": "v0"}, "resumeRetour": "Le carnet a brûlé. Le voïévode épargnera Matveï si Vera retire la page de la plainte qui le nomme.", "resumeSi": {"plainte_portee": "La plainte est partie par la piste du nord. Le voïévode jugera la mort de Semion si l'on ne rappelle pas le coureur.", "fosses_creusees": "Borislav, déchu, a vu vos fosses. Il les livrera, sauf si tu jures que la page du carnet sur lui est un faux.", "borislav_dementi": "Tu as juré que Borislav mentait. Sa page dans le carnet d'Ilya devient suspecte : Ilya doit-il la rejurer ?"}, "absentsSi": {"borislav_dementi": ["gleb", "borislav", "matvei"]}}, "6": {"t": "Le compte de chacun", "resume": "Le voïévode exige que chaque famille avoue ce qu'elle a caché au tribut, Vera la première. Le carnet d'Ilya a tous les noms : décide si tu le livres en entier.", "absents": ["gleb"], "debut": "a", "debutRetour": "r1", "absentsRetour": ["gleb", "matvei", "borislav"], "noeuds": {"a": {"qui": "borislav", "txt": "Le voïévode Borislav Andreïevitch : « Ta cheffe a fait écrire au tsar. Sa plainte partira au printemps. Avant elle, le tsar recevra un compte juste, de ma main : chaque peau cachée depuis six hivers, famille par famille. Vera avouera la première. Et le carnet de ton marchand a tous les noms. Apporte-le-moi. »", "rep": [{"l": "Je vais voir Vera.", "va": "b"}, {"l": "Je vais voir Ilya.", "va": "c"}]}, "b": {"qui": "vera", "txt": "Vera : « J'avouerai demain : la vente, et douze peaux de plus, vendues l'an passé pour payer la dette de Bogdan. Ce jour devait venir. Mais les autres familles ont caché pour manger, comme moi. Si tu donnes tout le carnet, Kobor entier paiera. Si tu ne donnes que ma page, je paierai pour tous. Je l'accepte. »", "rep": [{"l": "Et Oustina ?", "va": "d"}, {"l": "Je vais voir Ilya.", "va": "c"}]}, "c": {"qui": "ilya", "txt": "Ilya : « Tout est noté. Qui m'a vendu quoi, depuis six hivers. Et une page que personne n'attend : les peaux que les hommes du voïévode me revendent, chaque hiver. » Il baisse la voix. « Borislav veut le carnet complet. Il ne sait pas ce qu'il demande. Je ne le porterai pas moi-même : je n'arrive pas à vendre mes clients. »", "rep": [{"l": "Je vais voir Oustina.", "va": "d", "trace": "page_voievode"}, {"l": "Je vais voir Matveï.", "va": "e", "trace": "page_voievode"}]}, "d": {"qui": "oustina", "txt": "Oustina : « Vingt peaux, sous les claies du séchoir. Pour nos vieux jours. Bogdan le sait : il les a tannées lui-même. Cinq, je les ai vendues à Ilya pour du sel : mon nom est dans le carnet. S'il est lu, on viendra chercher les quinze autres. » Elle te regarde. « Je ne te demande rien. Je voulais que tu le saches. »", "rep": [{"l": "Je dois parler à Matveï.", "va": "e"}, {"l": "Je comprends. Allons au cercle.", "va": "f", "trace": "oustina_avoue"}]}, "e": {"qui": "matvei", "txt": "Matveï, sous la garde d'un soldat : « Si tu donnes tout, le voïévode tiendra chaque famille par son nom. Si tu caches, ça pourrira sous la neige, comme Semion. J'ai choisi de cacher, il y a quarante ans. Je ne sais toujours pas si j'aurais dû parler. »", "rep": [{"l": "Aller au cercle de pierres.", "va": "f"}]}, "f": {"qui": "borislav", "final": true, "txt": "Au cercle, Vera a tout avoué, sans baisser les yeux. Le hameau attend la suite en silence. Le voïévode Borislav tend la main vers toi : « Le carnet. Toutes les pages. »", "txtTrace": {"oustina_avoue": "Au premier rang, Oustina tient la main de Bogdan.", "page_voievode": "Tu sais ce qu'il y a à la dernière page. Lui ne le sait pas."}, "fin": [{"vers": 7, "l": "Toutes les pages, à voix haute.", "prix": "Chaque famille paie. Oustina perd ses quinze peaux.", "epreuve": "dialogue", "resultat": "Tu lis le carnet au cercle, nom par nom, jusqu'à la page du voïévode. Borislav ne peut plus rien cacher : tout Kobor a entendu, et chaque famille paie jusqu'à sa dernière peau.", "trace": "carnet_complet"}, {"vers": 5, "l": "Seulement la page de Vera.", "prix": "Vera paie pour tout Kobor. La page du voïévode brûle avec les autres.", "epreuve": "combat", "resultat": "Tu arraches les autres pages et tu les jettes au feu. Vera porte seule la dette de Kobor, et Borislav, sans le savoir, vient d'être sauvé.", "trace": "pages_brulees", "combat": "Les hommes du voïévode veulent t'arracher le carnet entier avant que tu en brûles les pages."}]}, "r1": {"lieu": "camp", "txt": "Le voïévode est tombé, Matveï est parti avec le convoi. Sous le séchoir, dix peaux dorment dans la fosse de Bogdan. Ce matin, un traîneau est arrivé : le scribe du nouveau voïévode. Personne ne sait encore qui est son maître. Il veut compter les réserves de chaque famille avant l'hiver prochain.", "txtTrace": {"cache_hiver": "La neige fraîche cache mal la terre remuée sous le séchoir."}, "rep": [{"l": "Parler à Vera.", "va": "r2"}, {"l": "Parler à Ilya.", "va": "r3"}]}, "r2": {"qui": "vera", "txt": "Vera : « Le scribe m'a demandé si Kobor cache encore quelque chose. J'ai dit que j'irais voir. Je sais pour la fosse. Tout le hameau le sait. Si on la déclare, Bogdan passe pour l'homme qui a menti deux fois. Si on se tait, on recommence, avec un maître qu'on ne connaît pas encore. »", "rep": [{"l": "Aller voir Bogdan.", "va": "r4"}]}, "r3": {"qui": "ilya", "txt": "Ilya : « Le scribe m'a montré sa liste. Elle est courte, et propre. Il ne cherche pas les voleurs. Il cherche ce que Kobor peut payer. » Il frotte ses mains. « Un maître qui sait compter, c'est bien. Un maître qui sait ce que tu caches, c'est autre chose. Bogdan devrait y penser. »", "rep": [{"l": "Aller voir Bogdan.", "va": "r4"}]}, "r4": {"qui": "bogdan", "final": true, "txt": "Bogdan : « Trois familles sont venues cette nuit. Elles veulent creuser, elles aussi, chacune sa fosse, avant que le scribe compte. Ou alors je vais le voir, et je lui montre la mienne. Dis-moi. Moi, je n'ai plus d'avis : j'ai déjà menti une fois pour tout le monde. »", "fin": [{"vers": 7, "l": "Montre ta fosse au scribe.", "prix": "Les dix peaux partent. Bogdan reste l'homme qui a menti deux fois.", "epreuve": "dialogue", "resultat": "Bogdan conduit le scribe sous le séchoir. Le scribe note dix peaux sans un mot, et Kobor n'a plus rien à cacher au nouveau maître.", "trace": "fosse_declaree"}, {"vers": 5, "l": "Creusez tous, avant qu'il compte.", "prix": "Kobor recommence à cacher, famille par famille.", "epreuve": "dialogue", "resultat": "Cette nuit-là, quatre fosses s'ouvrent sous la neige. Le scribe repart avec un compte propre, et faux.", "trace": "fosses_creusees"}]}, "v1": {"qui": "ilya", "txt": "Ilya : « Le carnet a brûlé. Mais je n'oublie pas un compte. En trois nuits, je l'ai réécrit de mémoire : chaque famille, et la page des hommes du voïévode. Borislav l'a su. Il veut cette copie, toutes les pages, pour son compte au tsar. Vera a déjà tout avoué au cercle. » Il te tend les feuilles. « Moi, je ne les porterai pas. »", "rep": [{"l": "Je vais voir Oustina.", "va": "d", "trace": "page_voievode"}, {"l": "Je vais voir Matveï.", "va": "e", "trace": "page_voievode"}]}, "x1": {"qui": "borislav", "txt": "Le voïévode Borislav Andreïevitch : « Votre plainte court vers le nord. Elle arrivera. Moi aussi, j'écris au tsar, et ma lettre ira plus vite : un compte juste, chaque peau cachée depuis six hivers, famille par famille. Vera avouera la première. Le carnet de ton marchand a tous les noms. Apporte-le-moi. »", "rep": [{"l": "Je vais voir Vera.", "va": "b"}, {"l": "Je vais voir Ilya.", "va": "c"}]}, "y1": {"lieu": "camp", "txt": "L'escorte a vidé les fosses et emmené Borislav. Kobor n'a plus rien sous la neige. Le scribe du nouveau voïévode est là. Il ne compte plus les peaux : il veut savoir qui a creusé.", "rep": [{"l": "Aller voir Vera.", "va": "y2"}], "txtTrace": {"page_rejuree": "Ilya a rejuré sa page. Le scribe sait que tu as menti une fois."}}, "y2": {"qui": "vera", "final": true, "txt": "Vera : « Borislav a donné au scribe les noms de ceux qui ont creusé. Mais la parole d'un voïévode déchu ne vaut rien sans témoin. Si tu confirmes, quatre familles paieront l'amende des peaux cachées, Bogdan en tête. Si tu dis que Borislav a menti pour se venger, le scribe repart, et Kobor commence avec son nouveau maître sur un mensonge. »", "fin": [{"vers": 7, "l": "Donne les noms au scribe.", "prix": "Quatre familles paient l'amende des peaux cachées, Bogdan en tête.", "epreuve": "dialogue", "resultat": "Le scribe note quatre noms sans lever les yeux. Kobor paie, et plus personne ne pourra le faire chanter.", "trace": "noms_donnes"}, {"vers": 5, "l": "Dis que Borislav a menti.", "prix": "Kobor ment au nouveau maître dès le premier jour, et le scribe recomptera tout Kobor.", "epreuve": "dialogue", "resultat": "Tu jures que Borislav a menti pour se venger. Le scribe referme son registre, et Kobor respire, un peu trop vite.", "trace": "borislav_dementi"}], "txtTrace": {"page_rejuree": "« Cette fois, le scribe ne te croira pas sur parole. Si tu redis que Borislav ment, il comptera lui-même chaque fosse. »"}}, "z1": {"lieu": "camp", "txt": "Le scribe est revenu plus tôt qu'il ne l'avait dit. Il a vu la neige remuée sous le séchoir. Il ne demande rien. Il attend.", "rep": [{"l": "Parler à Vera.", "va": "r2"}]}}, "debutSi": {"page_gardee": "v1", "plainte_courue": "x1", "fosses_livrees": "y1", "cache_hiver_bis": "z1", "page_rejuree": "y1"}, "resumeRetour": "Le scribe du nouveau voïévode compte les réserves. Bogdan doit-il montrer sa fosse, ou chaque famille creuser la sienne ?", "resumeSi": {"page_gardee": "Le carnet a brûlé, mais Ilya l'a réécrit de mémoire. Le voïévode veut toutes les pages pour son compte au tsar.", "plainte_courue": "La plainte court vers le nord. Le voïévode veut le carnet d'Ilya, toutes les pages, pour écrire au tsar avant elle.", "fosses_livrees": "L'escorte a vidé les fosses. Le scribe veut savoir qui a creusé : donner les noms, ou dire que Borislav a menti ?", "cache_hiver_bis": "Le scribe du nouveau voïévode compte les réserves. Bogdan doit-il montrer sa fosse, ou chaque famille creuser la sienne ?", "page_rejuree": "Ilya a rejuré sa page contre Borislav. Le scribe revient : donner les noms de ceux qui ont creusé, ou non ?"}, "absentsSi": {"fosses_livrees": ["gleb", "borislav", "matvei"], "page_rejuree": ["gleb", "borislav", "matvei"]}}, "7": {"t": "Le séchoir vide", "resume": "Kobor n'a plus rien de caché, et plus rien en réserve. Bogdan veut enfouir dix peaux pour l'hiver : c'est la fin du pôle Vérité.", "absents": ["gleb", "matvei", "borislav"], "debut": "a", "noeuds": {"a": {"lieu": "pierre", "txt": "Le Coffre est ouvert, et vide. Le dégel a tout rendu : Semion dans sa tombe, les peaux cachées, les noms. Le voïévode est tombé, Gleb aussi. Personne ne sait qui viendra à leur place. La plainte de Vera partira au printemps, par la piste du nord. Kobor n'a plus de maître corrompu. Il n'a plus de réserve non plus.", "rep": [{"l": "Aller voir Vera.", "va": "b"}, {"l": "Aller droit au séchoir.", "va": "c"}], "txtTrace": {"plainte_courue": "La plainte, elle, est déjà loin sur la piste du nord."}}, "b": {"qui": "vera", "txt": "Vera : « Tout le monde sait tout, maintenant. On se regarde en face, au camp. Oustina m'a demandé : « Jusqu'à quand ? » J'ai dit : « Jusqu'au printemps, et le grain d'Ilya. » Elle a dit : « Eh bien, tenons encore. » Et elle est retournée au séchoir. » Vera détourne les yeux. « Bogdan veut te parler. Je devine pourquoi. »", "rep": [{"l": "Aller au séchoir.", "va": "c"}]}, "c": {"qui": "bogdan", "final": true, "txt": "Bogdan : « Une fosse sous le séchoir. Dix peaux, juste de quoi tenir si le grain ne vient pas. Personne ne demandera. Oustina dit oui. » Il plante sa pelle dans la neige. « Toi, tu as tout fait sortir de la glace. Tu nous laisses y remettre une seule chose ? »", "fin": [{"vers": 6, "l": "Creusez. Dix peaux, pas une de plus.", "prix": "Kobor recommence à mentir, un peu.", "epreuve": "dialogue", "resultat": "Bogdan creuse sous le séchoir pendant la nuit. Le gel reprend une mince couche du sol, juste assez pour garder un secret.", "trace": "cache_hiver"}], "refus": "Quitter Bogdan : la fosse restera vide"}, "w1": {"qui": "bogdan", "final": true, "txt": "Bogdan : « J'ai montré ma fosse au scribe. Il a noté dix peaux et il est reparti. Une autre fosse, dix peaux, il ne la verra pas. Oustina dit non, cette fois. Moi, je dis : juste de quoi tenir si le grain ne vient pas. »", "fin": [{"vers": 6, "l": "Creusez. Dix peaux, pas une de plus.", "prix": "Kobor recommence à mentir, un peu, et Oustina ne te le pardonne pas.", "epreuve": "dialogue", "resultat": "Bogdan creuse seul sous le séchoir pendant la nuit. Le gel reprend une mince couche du sol, juste assez pour garder un secret.", "trace": "cache_hiver_bis"}], "refus": "Quitter Bogdan : la fosse restera vide"}}, "debutSi": {"fosse_declaree": "w1"}, "resumeSi": {"fosse_declaree": "Bogdan a montré sa fosse au scribe. Il veut en creuser une autre, en secret."}}, "-1": {"t": "Le rapport de Gleb", "resume": "Bogdan attend au fort le convoi des mines. Gleb veut ton nom de témoin sur son rapport : signe-le, ou rouvre l'enquête.", "absents": ["bogdan", "borislav"], "debut": "a", "debutRetour": "r1", "noeuds": {"a": {"qui": "vera", "txt": "Vera : « Bogdan est parti à l'aube, enchaîné, pour le fort. Au printemps, le convoi l'emmènera aux mines. J'ai fait écrire au tsar contre le voïévode et contre Gleb. Chaque famille a mis sa marque. La plainte partira au printemps, par la piste du nord. D'ici là, elle reste cousue dans mon manteau. Gleb veut un témoin pour son rapport : toi. Et Ilya s'impatiente. »", "rep": [{"l": "Je vais voir Ilya", "va": "b"}, {"l": "Qu'en dit le hameau ?", "va": "c"}, {"l": "Et le vieux Matveï ?", "va": "e"}]}, "b": {"qui": "ilya", "txt": "Ilya, près de sa barge prise dans la glace : « J'ai été payé. Mais ton inspecteur rôde autour de ma barge. Si on me questionne, je dirai d'où viennent les peaux. Je ne mentirai pas pour Kobor gratis. »", "rep": [{"l": "Prends mon argent à la place", "va": "e", "trace": "paye_ilya"}, {"l": "Tu te tairas. De gré ou non.", "va": "f", "trace": "menace_ilya"}]}, "f": {"lieu": "camp", "txt": "Au camp, devant la barge, les deux gardes d'Ilya posent la main sur leur hache. On ne menace pas leur maître sans payer.", "combat": "Les gardes d'Ilya défendent leur maître.", "gagne": "e", "apres": "Ilya range son carnet. « Je me tairai. Pour l'instant. » Il n'oubliera pas ton visage."}, "c": {"lieu": "cercle", "txt": "Au cercle de pierres, les trappeurs parlent bas. « Bogdan, voleur ? Il n'a jamais rien pris à personne. » Au milieu d'eux, Oustina se tait et te regarde.", "rep": [{"l": "Dire : « Bogdan a avoué. »", "va": "e", "trace": "repete_aveu"}, {"l": "Ne rien dire", "va": "c2"}]}, "c2": {"qui": "oustina", "txt": "Oustina te suit hors du cercle. « Tu n'as rien dit. Les autres parlent, toi tu te tais. Tu sais quelque chose. Mon mari ment pour quelqu'un, je le sens. Je ne te demande pas qui. Pas encore. »", "rep": [{"l": "Aller voir Matveï", "va": "e", "trace": "silence_oustina"}]}, "e": {"qui": "matvei", "txt": "Matveï, devant le Coffre : « J'ai vu Bogdan porter les peaux jusqu'au traîneau. Je n'ai pas vu pour qui. Écris ça, si on te demande. C'est vrai, et ça ne dit rien. Il y a quarante ans, on a déjà fermé une porte ici. On dort mal, après. »", "rep": [{"l": "Aller signer chez Gleb", "va": "g"}]}, "g": {"qui": "gleb", "final": true, "txt": "Gleb : « Mon rapport tient en deux phrases : Bogdan a sorti les peaux du Coffre. Bogdan a avoué. Tout est vrai. Signe en témoin, et au printemps il part avec le convoi. Sinon, dis-moi ce qui manque. »", "txtTrace": {"paye_ilya": "Ilya ne parlera pas : tu l'as payé.", "menace_ilya": "Ilya se tait, mais par peur.", "repete_aveu": "Le hameau t'a entendu dire que Bogdan a avoué.", "silence_oustina": "Tu penses à Oustina : « Tu sais quelque chose. »"}, "fin": [{"vers": -2, "l": "Je signe.", "prix": "Bogdan partira aux mines au printemps. Ce n'est plus son aveu : c'est ta signature.", "epreuve": "dialogue", "resultat": "Gleb souffle sur l'encre. L'affaire est close, et le givre gagne la porte du Coffre.", "trace": "signe_rapport"}, {"vers": 0, "l": "Il manque un nom.", "prix": "L'enquête rouvre. Vera et le grain sont de nouveau en danger.", "epreuve": "combat", "combat": "Des trappeurs fidèles à Vera veulent t'empêcher de rouvrir l'affaire.", "resultat": "Gleb déchire le rapport. On fait revenir Bogdan du fort, les fers aux chevilles, et tout est à refaire.", "trace": "rapport_dechire"}]}, "r1": {"lieu": "cercle", "txt": "Au conseil, on a dit : « Bogdan n'a rien gardé pour lui. » Oustina garde la ligne de son mari. Mais la phrase court le hameau : si Bogdan n'a rien gardé, qui a gardé quoi ? Ce matin, Gleb a convoqué Ilya.", "rep": [{"l": "Aller voir Ilya", "va": "r2"}, {"l": "Aller voir Vera", "va": "r3"}]}, "r2": {"qui": "ilya", "txt": "Ilya : « Gleb m'a interrogé une heure. Je n'ai rien dit. Encore. Il a ton rapport sur la table, avec ton nom dessous. Il dit qu'un témoin qui change d'avis, ça se pend aussi bien qu'un voleur. »", "rep": [{"l": "Aller voir Gleb", "va": "rg"}]}, "r3": {"qui": "vera", "txt": "Vera : « Ta phrase était vraie. Elle a sauvé la ligne d'Oustina. Elle peut aussi me perdre. Gleb n'attendait que ça : un doute. Si tu retires ton nom, ma plainte part avec moi au Coffre. Je ne te dirai pas quoi faire. »", "rep": [{"l": "Aller voir Gleb", "va": "rg", "trace": "vera_retour"}]}, "rg": {"qui": "gleb", "final": true, "txt": "Gleb, ton rapport à la main : « Bogdan n'a rien gardé pour lui, dis-tu. Alors pour qui l'a-t-il fait ? Ton nom est sous ce rapport. Tu le confirmes, et j'oublie la phrase du conseil. Ou tu le retires, et on recommence tout. »", "txtTrace": {"vera_retour": "Tu revois Vera : « Je ne te dirai pas quoi faire. »", "rien_garde": "Il te rend la phrase du conseil, mot pour mot."}, "fin": [{"vers": -2, "l": "Je confirme mon rapport.", "prix": "Bogdan reste au fort, puis les mines. La phrase du conseil ne compte plus.", "epreuve": "combat", "resultat": "Gleb range le rapport. Au cercle, on cesse de chuchoter, et Bogdan reste promis au convoi.", "trace": "rapport_confirme", "combat": "Les compagnons de chasse de Bogdan barrent la tente de Gleb : ils ne veulent pas que tu confirmes."}, {"vers": 0, "l": "Je retire mon nom.", "prix": "L'enquête rouvre. Vera et le grain sont de nouveau en danger.", "epreuve": "dialogue", "resultat": "Gleb déchire le rapport. On fait revenir Bogdan du fort, les fers aux chevilles, et tout est à refaire.", "trace": "rapport_dechire"}]}}, "resumeRetour": "Ta phrase au conseil a semé le doute. Gleb te demande de confirmer ton rapport contre Bogdan, ou de retirer ton nom."}, "-2": {"t": "La ligne de Bogdan", "resume": "Le conseil veut prendre à Oustina la ligne de pièges de son mari « voleur ». Vera te demande de parler à sa place.", "absents": ["bogdan", "borislav"], "debut": "a", "debutRetour": "r1", "noeuds": {"a": {"qui": "vera", "txt": "Vera : « Ce soir, le conseil veut la ligne de pièges de Bogdan. La règle dit : un voleur qui s'est enrichi perd sa ligne. Si je le défends, on me demandera pourquoi. Va voir. Puis parle pour moi. »", "rep": [{"l": "Voir la ligne de Bogdan", "va": "b", "trace": "ligne_pleine"}, {"l": "Parler à Oustina", "va": "d"}, {"l": "Parler à Matveï", "va": "f"}]}, "b": {"lieu": "belvedere", "txt": "Sous le belvédère, la ligne de Bogdan longe le ruisseau gelé. Des loups maigres tournent autour des pièges.", "combat": "Des loups affamés pillent la ligne de pièges.", "gagne": "g", "apres": "Trois zibelines prises en une seule nuit. Les autres lignes en donnent une par semaine. Voilà pourquoi le conseil la veut."}, "d": {"qui": "oustina", "txt": "Oustina, au séchoir : « Sans la ligne, il me reste le séchoir et l'hiver. Je ne te demande pas si mon mari est coupable. Pas encore. »", "rep": [{"l": "Je parlerai pour toi.", "va": "g", "trace": "promesse_oustina"}, {"l": "Je ne peux rien promettre.", "va": "f"}]}, "f": {"qui": "matvei", "txt": "Matveï : « Il y a quarante ans, ce hameau a déjà choisi entre un homme et tout le monde. On a eu raison, je crois. Depuis, je compte les hivers. Le conseil choisira pareil, et il aura raison aussi. »", "rep": [{"l": "Aller au conseil", "va": "g"}]}, "g": {"qui": "vera", "final": true, "txt": "Au cercle, Vera, tout bas : « Si je dis que Bogdan n'a rien gardé pour lui, ils demanderont où sont les peaux. Si je me tais, Oustina perd sa ligne. Parle, toi. Ils t'écouteront. »", "txtTrace": {"promesse_oustina": "Tu as promis à Oustina de parler pour elle.", "ligne_pleine": "Tu sais ce que vaut cette ligne : trois peaux en une nuit."}, "fin": [{"vers": -3, "l": "Partagez la ligne de Bogdan.", "prix": "Oustina perd la ligne de son mari. Le hameau reste soudé.", "epreuve": "dialogue", "resultat": "Les trappeurs se partagent la ligne. Vera ne lève pas les yeux, et le ruisseau gèle jusqu'au fond.", "trace": "ligne_partagee"}, {"vers": -1, "l": "Bogdan n'a rien gardé pour lui.", "prix": "Une phrase vraie. Le conseil doute, et Gleb l'apprendra.", "epreuve": "combat", "combat": "Des trappeurs en colère veulent savoir qui protège un voleur.", "resultat": "La ligne reste à Oustina. Mais on chuchote, et Gleb rouvre son carnet.", "trace": "rien_garde"}]}, "r1": {"qui": "oustina", "txt": "Oustina, au séchoir : « Tu m'as dit la vérité. Il a porté les peaux pour Vera. Pour elle, qui a payé notre dette. Et c'est elle qui a laissé le conseil me prendre sa ligne. Je me tais pour le hameau. Mais je veux la ligne de mon mari. Devant tous. »", "rep": [{"l": "Je le dirai à Vera.", "va": "r3", "trace": "porte_parole"}, {"l": "Va voir Matveï avec moi.", "va": "r2"}]}, "r2": {"qui": "matvei", "txt": "Matveï : « Rendre la ligne devant tous, c'est dire pourquoi on la rend. Le conseil n'est pas sot. Une ligne rendue, c'est un voleur qui n'en est pas un. Et un voleur qui n'en est pas un, ça cherche un autre voleur. »", "rep": [{"l": "Aller voir Vera", "va": "r3"}]}, "r3": {"qui": "vera", "final": true, "txt": "Vera : « Oustina sait. Elle veut la ligne, devant le conseil. Si je la rends, je dois dire : Bogdan n'a rien gardé pour lui. Le hameau doutera, et Gleb aussi. Si je refuse, Oustina me hait, et elle a raison. Que dois-je faire ? »", "txtTrace": {"porte_parole": "Tu viens de la part d'Oustina, et Vera le voit.", "ligne_partagee": "Les trappeurs ont déjà posé leurs pièges sur cette ligne."}, "fin": [{"vers": -3, "l": "Garde le silence, Vera.", "prix": "Oustina reste sans ligne et ne pardonnera pas. Le secret tient.", "epreuve": "combat", "resultat": "Vera ne dit rien au conseil. Oustina passe devant elle sans la voir, et le ruisseau regèle.", "trace": "ligne_gardee", "combat": "Les cousins d'Oustina viennent reprendre la ligne de force : il faut les repousser pour que le silence tienne."}, {"vers": -1, "l": "Rends-lui la ligne. Devant tous.", "prix": "« Bogdan n'a rien gardé » : le conseil doute, Gleb l'apprendra.", "epreuve": "dialogue", "resultat": "Oustina reprend la ligne de son mari. Mais on chuchote, et Gleb rouvre son carnet.", "trace": "rien_garde"}]}, "s1": {"qui": "oustina", "txt": "Oustina, au séchoir : « Au conseil, une phrase m'a rendu la ligne de mon mari : il n'a rien gardé pour lui. Puis tu as confirmé à Gleb son rapport : Bogdan a avoué. Le conseil se réunit encore ce soir. Il veut savoir laquelle des deux phrases compte. »", "rep": [{"l": "Aller au cercle", "va": "s2"}, {"l": "Qu'en pense Vera ?", "va": "s3"}]}, "s2": {"lieu": "cercle", "txt": "Au cercle, les trappeurs ont posé le rapport de Gleb sur une pierre. L'un d'eux le montre du doigt : « Un voleur qui a avoué perd sa ligne. C'est la règle. Ou alors il n'a pas volé, et il faut nous dire qui. »", "rep": [{"l": "Trouver Vera", "va": "sg"}]}, "s3": {"qui": "vera", "txt": "Vera, devant sa porte : « Les deux phrases sont vraies. Bogdan n'a rien gardé, et il a avoué. Le conseil ne veut pas deux vérités. Il en veut une, et un voleur. »", "rep": [{"l": "Aller au conseil", "va": "sg", "trace": "vera_deux_phrases"}]}, "sg": {"qui": "vera", "final": true, "txt": "Vera, au cercle : « Ils attendent. Si le rapport compte, Oustina perd la ligne, et le secret tient. Si ta phrase du conseil compte, ils chercheront qui a vraiment pris les peaux. Parle. C'est ton nom sur les deux. »", "txtTrace": {"vera_deux_phrases": "« Deux vérités », a dit Vera. Il faut en choisir une."}, "fin": [{"vers": -3, "l": "Le rapport compte. Reprenez la ligne.", "prix": "Oustina perd la ligne qu'on venait de lui rendre. Le secret tient.", "epreuve": "dialogue", "resultat": "Les trappeurs reprennent la ligne de Bogdan. Oustina rend les pièges un par un, sans un mot.", "trace": "ligne_partagee"}, {"vers": -1, "l": "Ma phrase du conseil compte.", "prix": "Oustina garde la ligne. Le conseil cherche un autre voleur.", "epreuve": "combat", "combat": "Des trappeurs en colère veulent savoir qui protège un voleur.", "resultat": "La ligne reste à Oustina. Le conseil murmure un autre nom, et Gleb rouvre son carnet.", "trace": "rien_garde"}]}}, "debutSi": {"rapport_confirme": "s1"}, "resumeRetour": "Oustina sait pour qui Bogdan a porté les peaux. Elle exige qu'on lui rende la ligne de son mari, devant tous.", "resumeSi": {"rapport_confirme": "Tu as dit deux choses vraies et contraires : « Bogdan n'a rien gardé » et « Bogdan a avoué ». Le conseil veut savoir laquelle compte."}}, "-3": {"t": "La question d'Oustina", "resume": "Une lettre de Bogdan arrive du fort. Oustina veut savoir ce qu'a fait son mari : tu dois lui répondre.", "absents": ["bogdan", "borislav"], "debut": "a", "debutRetour": "r1", "noeuds": {"a": {"qui": "oustina", "txt": "Oustina : « Bogdan m'a écrit du fort. Je ne sais pas lire. Ilya a porté la lettre. Je crois qu'il ment pour quelqu'un. Mais s'il a volé, je veux le savoir. Lis-la-moi. Ou va demander à Vera. Ce soir, tu me diras ce qu'il a fait. »", "rep": [{"l": "Lire la lettre", "va": "b"}, {"l": "Voir Vera", "va": "c"}, {"l": "Voir Ilya, qui l'a portée", "va": "d"}]}, "b": {"lieu": "camp", "txt": "La lettre tient en trois lignes, d'une main de scribe : « Je n'ai rien volé. Ne crois personne. Garde ce que tu sais où tu sais. » Il l'a dictée devant un garde. Oustina blêmit à la dernière phrase, et regarde vers le séchoir.", "rep": [{"l": "Que gardes-tu au séchoir ?", "va": "f", "trace": "peaux_oustina"}, {"l": "Lui répondre maintenant", "va": "g", "trace": "lu_lettre"}]}, "f": {"lieu": "camp", "txt": "Derrière le séchoir, la neige est grattée. Des gloutons ont flairé quelque chose sous les claies.", "combat": "Des gloutons fouillent la cache sous le séchoir.", "gagne": "g", "apres": "Sous les claies : vingt zibelines, roulées dans de la toile. Bogdan les a tannées lui-même. Oustina les a cachées au tribut, pour leurs vieux jours."}, "c": {"qui": "vera", "txt": "Vera : « Si elle sait, tout le hameau saura avant la nuit. Bogdan aura payé pour rien, et moi je serai au Coffre, avec ma plainte. Tu peux ne pas mentir. Dis-lui seulement ce qu'il a fait. Pas pour qui. »", "rep": [{"l": "Retourner voir Oustina", "va": "g", "trace": "conseil_vera"}]}, "d": {"qui": "ilya", "txt": "Ilya : « J'ai pris la lettre au fort. Bogdan tousse. Il ne survivra pas à la route des mines. Je te le dis parce que personne d'autre ne le fera. »", "rep": [{"l": "Retourner voir Oustina", "va": "g", "trace": "bogdan_malade"}]}, "g": {"qui": "oustina", "final": true, "txt": "Oustina : « Une seule question. Qu'a fait mon mari ? »", "txtTrace": {"peaux_oustina": "Elle voit que tu as trouvé ses vingt peaux. « Moi aussi, je cache. Alors toi, ne me cache rien. »", "bogdan_malade": "Tu sais que Bogdan tousse, là-bas.", "conseil_vera": "Vera t'a soufflé : « Ce qu'il a fait. Pas pour qui. »"}, "fin": [{"vers": -4, "l": "Il a sorti les peaux du Coffre.", "prix": "Pas un mot faux. Oustina croira qu'il a volé pour lui.", "epreuve": "dialogue", "resultat": "Oustina hoche la tête et jette la lettre au feu. Elle ne prononce plus le nom de Bogdan.", "trace": "trompe_oustina"}, {"vers": -2, "l": "Il les a portées pour Vera.", "prix": "Oustina sait. Le secret du hameau tient à sa colère.", "epreuve": "dialogue", "resultat": "Oustina pleure, puis se tait. Elle garde le secret, mais elle ne salue plus Vera.", "trace": "oustina_sait"}]}, "r1": {"qui": "oustina", "txt": "Sur le registre, tu as tenu tête à Gleb. Furieux, il rouvre l'enquête et interroge les témoins. Oustina t'attend au séchoir : « Gleb m'a interrogée. Il dit que Bogdan n'a pas touché une pièce. Qu'il a porté les peaux pour quelqu'un. Toi, tu m'as dit : il a sorti les peaux du Coffre. C'était vrai. Mais c'était tout ? »", "rep": [{"l": "Que t'a demandé Gleb ?", "va": "r2"}, {"l": "Je te réponds maintenant.", "va": "rg"}], "txtTrace": {"aveu_tient": "Les greniers sont vides : le voïévode a pris le grain. Vera sera jugée au dégel."}}, "r2": {"qui": "gleb", "txt": "Gleb, au camp : « Ta phrase à Oustina était exacte. Je les aime, les phrases exactes. Si elle apprend pour qui son mari a porté ces peaux, elle le dira devant moi. Une femme en colère est un bon témoin. »", "rep": [{"l": "Retourner voir Oustina", "va": "rg", "trace": "gleb_attend"}]}, "rg": {"qui": "oustina", "final": true, "txt": "Oustina : « Je te repose la question, autrement. Ce que tu m'as dit, c'était tout ? »", "txtTrace": {"gleb_attend": "Gleb attend devant le séchoir. Il entendra la réponse.", "trompe_oustina": "La première fois, tu n'as pas dit un mot faux."}, "fin": [{"vers": -4, "l": "C'était tout.", "prix": "Cette fois, c'est un mensonge. Oustina n'aidera pas Gleb.", "epreuve": "dialogue", "resultat": "Oustina ferme la porte du séchoir. Gleb repart sans témoin, et Bogdan reste un voleur pour sa femme.", "trace": "ment_oustina"}, {"vers": -2, "l": "Non. Il les a portées pour Vera.", "prix": "Oustina sait, et Gleb tient peut-être son témoin.", "epreuve": "dialogue", "resultat": "Oustina pleure, puis se tait devant Gleb. Elle garde le secret, mais elle ne salue plus Vera.", "trace": "oustina_sait"}]}, "t1": {"qui": "oustina", "txt": "Oustina, au séchoir : « Je sais pour qui Bogdan a porté les peaux. Et Vera m'a laissé sans sa ligne. Si je dis tout à Gleb, Bogdan sort du fort, et Vera y entre. J'ai gardé la lettre de Bogdan. Je veux comprendre la dernière ligne avant de choisir. »", "rep": [{"l": "Relis-la-moi encore", "va": "t2"}, {"l": "Tu veux aller voir Gleb ?", "va": "tg", "trace": "oustina_gleb"}]}, "t2": {"lieu": "camp", "txt": "Tu relis la lettre : « Je n'ai rien volé. Ne crois personne. Garde ce que tu sais où tu sais. » Oustina : « Ce que je sais. Il parle de mes vingt peaux, sous les claies ? Ou de Vera ? »", "rep": [{"l": "Lui répondre", "va": "tg", "trace": "lu_lettre"}]}, "tg": {"qui": "oustina", "final": true, "txt": "Oustina : « Toi qui sais lire. « Garde ce que tu sais où tu sais. » De quoi parle-t-il ? Si c'est de Vera, je me tais. Sinon, je vais voir Gleb. »", "txtTrace": {"oustina_gleb": "Elle a déjà son manteau sur les épaules."}, "fin": [{"vers": -4, "l": "Il parle de Vera. Il veut ton silence.", "prix": "Tu fais dire à Bogdan ce qu'il n'a pas écrit. Oustina se taira.", "epreuve": "dialogue", "resultat": "Oustina plie la lettre et la range sous les claies, avec ses peaux. Elle ne va pas voir Gleb.", "trace": "lettre_detournee"}, {"vers": -2, "l": "Il parle de tes peaux. Le reste…", "prix": "« Le reste, c'est à toi. » Oustina peut perdre Vera.", "epreuve": "dialogue", "resultat": "Oustina reste longtemps devant la porte. Puis elle va au cercle réclamer la ligne de son mari, devant tous.", "trace": "oustina_sait"}]}}, "debutSi": {"ligne_gardee": "t1"}, "resumeRetour": "Gleb cherche un témoin contre Vera. Oustina te repose sa question : ce que tu lui as dit de Bogdan, c'était tout ?", "resumeSi": {"ligne_gardee": "Oustina sait tout et hésite à aller voir Gleb. Aide-la à comprendre la dernière ligne de la lettre de Bogdan."}}, "-4": {"t": "La route de Zverevo", "resume": "Gleb a tout compris. Il se taira si tu signes un registre truqué : Zverevo, le hameau voisin, remboursera le tribut de Kobor.", "absents": ["bogdan", "borislav"], "debut": "a", "debutRetour": "r1", "noeuds": {"a": {"qui": "gleb", "txt": "Gleb : « Je sais tout. Vera, le grain, Ilya. J'écris : peaux pillées sur la route, sur le tronçon de Zverevo. La coutume fait rembourser le hameau du tronçon : quarante peaux par hiver, dix hivers durant. Moi, je garde ma dîme. Il me faut un témoin qui signe, comme pour Bogdan. Toi. »", "rep": [{"l": "Qui paiera, à Zverevo ?", "va": "b"}, {"l": "Vera est d'accord ?", "va": "c"}, {"l": "Qui garde le registre ?", "va": "d"}], "txtTrace": {"ment_oustina": "Il ajoute : « Tu m'as refusé une fois. Puis je t'ai entendu mentir à Oustina. Tu sais te taire, finalement. »"}}, "b": {"qui": "ilya", "txt": "Ilya : « Zverevo a eu la même famine que vous. Je leur ai vendu du grain à crédit. S'ils paient votre tribut, ils ne me paieront jamais. Escorte-moi jusqu'à la route, je te montrerai quelque chose. »", "rep": [{"l": "Escorter Ilya", "va": "e", "trace": "vu_carnet"}, {"l": "Retourner voir Gleb", "va": "g"}]}, "e": {"lieu": "belvedere", "txt": "Sur la route du belvédère, des pillards attendent le traîneau d'Ilya.", "combat": "Des pillards attaquent le traîneau d'Ilya.", "gagne": "g", "apres": "Ilya ouvre son carnet. Une page entière : des peaux à l'estampille du trésor, déjà comptées, revendues par Gleb dans des sacs sans sceau. La dîme, prise deux fois. « Garde ça en tête. »"}, "c": {"qui": "vera", "txt": "Vera : « Zverevo ou nous. Je choisis nous. Ne me demande pas d'en être fière. Et ne me demande pas de signer ce registre moi-même. Je ne sais pas écrire. Je ne mettrai pas ma marque là-dessus. »", "rep": [{"l": "Aller voir Gleb", "va": "g", "trace": "vera_accepte"}]}, "d": {"qui": "matvei", "txt": "Matveï, devant le Coffre : « Le registre dort ici. Il y a quarante ans, j'y ai déjà réécrit une page. L'encre gèle, la page reste. Personne ne vient jamais la relire. Tu vois : ça marche. »", "rep": [{"l": "Aller voir Gleb", "va": "g"}]}, "g": {"qui": "gleb", "final": true, "txt": "Gleb, devant la Pierre d'éveil, le registre ouvert : « Une phrase, ta signature, et Kobor est en règle. Elle est vraie, en plus : le traîneau d'Ilya est bien passé par Zverevo. Alors ? »", "txtTrace": {"vu_carnet": "Tu sais qu'il prend la dîme deux fois. Lui ne sait pas que tu sais.", "vera_accepte": "Vera a dit oui, sans vouloir y mettre sa marque.", "trompe_oustina": "Tu connais déjà ce genre de phrase. Tu l'as dite à Oustina."}, "fin": [{"vers": -5, "l": "Signe : la route de Zverevo.", "prix": "Zverevo paiera quarante peaux par hiver, dix hivers. Gleb vole toujours.", "epreuve": "combat", "resultat": "Gleb souffle sur l'encre et range le registre dans le Coffre. Kobor est en règle ; Zverevo ne le sait pas encore.", "trace": "zverevo_paie", "combat": "Les hommes d'Ilya veulent arracher le registre : Zverevo lui doit déjà son grain."}, {"vers": -3, "l": "Je ne signerai pas.", "prix": "Gleb rouvre l'enquête et cherchera un témoin contre Vera.", "epreuve": "dialogue", "resultat": "Le registre reste vierge. Gleb part interroger les témoins, un par un.", "trace": "registre_refuse"}]}, "r1": {"lieu": "pierre", "txt": "Devant le voïévode, tu as avoué : le registre était faux. Zverevo ne doit plus rien. Mais Gleb a aussitôt montré Vera du doigt. Le grain d'hiver est parti sur les traîneaux du voïévode, et Vera sera jugée au dégel. Kobor regarde ses greniers vides.", "rep": [{"l": "Aller voir Vera", "va": "r2"}, {"l": "Aller voir Ilya", "va": "r3"}]}, "r2": {"qui": "vera", "txt": "Vera : « Je serai jugée au dégel. Je ne fuirai pas, et je garde ma plainte. Mais Kobor n'a plus rien à manger. Gleb est venu cette nuit. Il a une offre. Pour toi, pas pour moi. Je ne veux pas savoir laquelle. »", "rep": [{"l": "Aller voir Gleb", "va": "rg", "trace": "vera_attend"}]}, "r3": {"qui": "ilya", "txt": "Ilya, près de sa barge : « Gleb voulait mon carnet. Je l'ai caché. Il a peur, maintenant : un inspecteur qui a écrit un faux, ça se juge aussi. Il va te proposer quelque chose. Ce sera généreux. Méfie-toi des hommes généreux qui ont peur. »", "rep": [{"l": "Aller voir Gleb", "va": "rg", "trace": "carnet_cache"}]}, "rg": {"qui": "gleb", "final": true, "txt": "Gleb : « Je retire mon accusation, et le grain revient à Kobor. Il suffit que tu dises au voïévode que tu as menti hier : le registre était juste, Zverevo paie. Tout le monde y gagne. Sauf Zverevo. »", "txtTrace": {"carnet_cache": "Ilya a caché son carnet. Gleb ne l'a pas.", "vera_attend": "Vera n'a pas voulu savoir. C'est toi qui choisis pour elle."}, "fin": [{"vers": -5, "l": "Je me dédis : Zverevo paie.", "prix": "Tu te dédis devant le voïévode : le knout pour faux témoin. Zverevo paiera dix hivers.", "epreuve": "dialogue", "resultat": "On te fouette devant le camp, pour faux témoin. Puis le voïévode rend le grain, et la page de Zverevo est recopiée à l'encre fraîche.", "trace": "se_dedit", "cout": {"pv": 3}}, {"vers": -3, "l": "Non. Mon aveu tient.", "prix": "Kobor passe l'hiver sans grain. Vera sera jugée au dégel.", "epreuve": "dialogue", "resultat": "Gleb range son offre. Il part interroger les témoins un par un, pour le procès de Vera.", "trace": "aveu_tient"}]}}, "resumeRetour": "Ton aveu a fait saisir le grain, et Vera sera jugée. Gleb rendra tout si tu te dédis devant le voïévode."}, "-5": {"t": "Le premier terme", "resume": "Gleb a écrit que le tribut a été pillé sur la route de Zverevo : le hameau voisin doit rembourser. Zverevo ne paie pas, et le voïévode arrive. Tu protèges Kobor ou tu avoues le faux.", "absents": ["bogdan"], "debut": "a", "debutRetour": "r1", "noeuds": {"a": {"qui": "gleb", "txt": "Gleb : « Le voïévode arrive ce soir. Zverevo doit rembourser notre tribut : quarante peaux par hiver, dix hivers. Ils n'ont pas payé le premier terme, et ils crient au faux registre. Leurs trappeurs descendent la rivière vers le camp. Moi, je n'ai rien vu. Toi non plus. »", "txtTrace": {"zverevo_paie": "Tu te souviens de l'encre fraîche : « pillé sur la route de Zverevo »."}, "rep": [{"l": "J'attends ceux de Zverevo au camp", "va": "b"}, {"l": "Ilya peut-il aider Zverevo ?", "va": "c"}, {"l": "Je vais parler à Matveï", "va": "d", "trace": "vu_matvei_5"}]}, "b": {"lieu": "camp", "txt": "Six trappeurs de Zverevo entrent dans le camp, la hache à la main. Leur chef ouvre son propre registre : « Aucun convoi n'a été pillé chez nous. Votre tribut n'est jamais passé par notre route. Et on nous fait payer dix hivers. »", "combat": "Les trappeurs de Zverevo viennent se payer eux-mêmes : ils veulent vider le séchoir de Kobor.", "gagne": "e", "apres": "Ils repartent sur la glace. Leur chef se retourne une fois : « Le voïévode nous croira, ou il vous croira. Pas les deux. »"}, "c": {"qui": "ilya", "txt": "Ilya : « Je prête à Zverevo de quoi payer ce premier terme. Plus personne ne crie ce soir. Mon prix : le grain de printemps de Kobor. Vous aurez faim en avril, mais vous aurez la paix devant le voïévode. »", "txtTrace": {"vu_carnet": "Il referme vite son carnet. Tu sais quelle page il cache."}, "rep": [{"l": "Marché conclu", "va": "e", "trace": "ilya_paye_voisin"}, {"l": "Trop cher. Je vais au camp", "va": "b"}]}, "d": {"qui": "matvei", "txt": "Matveï : « J'ai déjà vu ce soir-là, il y a quarante ans. Un hameau voisin qui crie. Puis un inspecteur, Semion, qui trouve nos peaux cachées et veut écrire au trésor. Puis la porte du Coffre, que j'ai fermée. Il fait froid en bas. Le froid garde tout. »", "rep": [{"l": "Il est toujours en bas ?", "va": "d2"}, {"l": "Je vais voir le voïévode", "va": "e"}]}, "d2": {"lieu": "pierre", "txt": "Devant la Pierre d'éveil, la porte du Coffre est blanche de givre. Sur le linteau, quelqu'un a gravé des traits, un par hiver. Tu en comptes quarante. Le dernier est frais.", "rep": [{"l": "Aller voir le voïévode", "va": "e"}]}, "r1": {"qui": "vera", "txt": "Vera : « J'ai gardé la plainte, cousue dans mon manteau. Alors le voïévode Borislav Andreïevitch exige ses présents, cent peaux pour lui. Et pour me punir, il rouvre l'affaire de Zverevo : il veut savoir qui ment. Si notre registre tombe, je tombe avec lui. »", "rep": [{"l": "Que veut Zverevo, maintenant ?", "va": "r2"}, {"l": "Et Oustina ?", "va": "r3"}]}, "r2": {"lieu": "camp", "txt": "Le chef de Zverevo t'attend au camp, seul, sans hache. « Dix hivers. Mes petits-enfants paieront encore pour vous. Dis la vérité au voïévode, et je dirai la mienne : chez nous aussi, l'automne a eu faim. Ta cheffe n'a pas volé pour elle. »", "rep": [{"l": "Aller voir le voïévode", "va": "rf", "trace": "zverevo_temoin"}]}, "r3": {"qui": "oustina", "txt": "Oustina : « Cent peaux de présents. Il prendra mes vingt, je le sais. Si tu dis que le registre est faux, Gleb accusera Vera, et Bogdan sera resté au fort pour rien. Si tu te tais, c'est Zverevo qui paie. Décide. Moi, je ne peux plus. »", "rep": [{"l": "Aller voir le voïévode", "va": "rf"}]}, "e": {"qui": "borislav", "final": true, "txt": "Le voïévode Borislav Andreïevitch, devant le feu : « Zverevo me doit le tribut de Kobor, sur dix hivers. Kobor ne me doit rien : Kobor est en règle. Zverevo dit que votre registre est faux. Toi, l'étranger, tu as tout vu. Qui ment ? »", "txtTrace": {"ilya_paye_voisin": "Derrière lui, Ilya compte déjà les charges du grain de printemps.", "vu_matvei_5": "Tu penses aux quarante traits sur le linteau.", "zverevo_temoin": "Le chef de Zverevo attend à la porte. Il a promis de parler pour Vera."}, "fin": [{"vers": -6, "l": "Zverevo ment", "prix": "Le chef de Zverevo part au fort, enchaîné. Zverevo paiera dix hivers pour Kobor. Kobor garde son grain.", "epreuve": "combat", "resultat": "Borislav fait enchaîner le chef de Zverevo. Kobor mange à sa faim, et le voïévode regarde Vera longtemps : « Une cheffe qui tient ses comptes. Nous reparlerons. » Le chef de Zverevo passe enchaîné devant la Pierre, sur les traces de Bogdan.", "trace": "voisin_accuse", "combat": "Les trappeurs de Zverevo refusent qu'on enchaîne leur chef."}, {"vers": -4, "l": "Notre registre est faux", "prix": "Zverevo est libéré. Mais Gleb, démasqué, accuse Vera de la vente : le grain d'hiver est saisi, Vera sera jugée au dégel.", "epreuve": "dialogue", "resultat": "Borislav efface la dette de Zverevo. Gleb montre Vera du doigt : le grain d'hiver part sur les traîneaux du voïévode, et Kobor regarde ses greniers vides.", "trace": "registre_avoue"}]}, "r0": {"qui": "vera", "txt": "Vera : « L'envoyé a lu le brouillon, puis me l'a rendu : rien ne part avant le convoi du printemps. J'ai perdu le sceau. Le voïévode Borislav Andreïevitch exige ses présents, cent peaux, et il rouvre l'affaire de Zverevo pour me punir. Si notre registre tombe, je tombe avec lui. »", "rep": [{"l": "Que veut Zverevo, maintenant ?", "va": "r2"}, {"l": "Et Oustina ?", "va": "r3"}]}, "rf": {"qui": "borislav", "final": true, "txt": "Le voïévode, devant le feu : « Une cheffe qui garde ses plaintes peut aussi garder un faux registre. Zverevo jure que le vôtre ment. Toi, l'étranger, tu as tout vu. Dis-le devant tous : qui ment ? Et pense aux cent peaux que Kobor me doit déjà. »", "txtTrace": {"zverevo_temoin": "Le chef de Zverevo attend à la porte. Il a promis de parler pour Vera."}, "fin": [{"vers": -6, "l": "Zverevo ment", "prix": "Le chef de Zverevo part au fort, enchaîné. Zverevo paiera dix hivers pour Kobor. Le voïévode reviendra vers Vera.", "epreuve": "combat", "resultat": "Borislav fait enchaîner le chef de Zverevo. Puis il se tourne vers Vera : « Tu vois ce que coûte un registre juste. Réfléchis encore à mon sceau. » Le chef de Zverevo passe enchaîné devant la Pierre, sur les traces de Bogdan.", "trace": "zverevo_condamne", "combat": "Les trappeurs de Zverevo refusent qu'on enchaîne leur chef."}, {"vers": -4, "l": "Notre registre est faux", "prix": "Zverevo est libéré. Mais Gleb, démasqué, accuse Vera de la vente : le grain d'hiver est saisi, Vera sera jugée au dégel.", "epreuve": "dialogue", "resultat": "Borislav efface la dette de Zverevo. Gleb montre Vera du doigt : le grain d'hiver part sur les traîneaux du voïévode, et Kobor regarde ses greniers vides.", "trace": "registre_avoue"}]}, "s1": {"qui": "gleb", "txt": "Gleb : « Tu t'es dédit devant le voïévode. Zverevo paie de nouveau, et le grain est rentré à Kobor. Mais ceux de Zverevo ont entendu ton premier aveu. Ils descendent la rivière. Le voïévode Borislav Andreïevitch est encore là : ce soir, il les juge. Ne te dédis pas deux fois. »", "rep": [{"l": "J'attends ceux de Zverevo au camp", "va": "b"}, {"l": "Ilya peut-il aider Zverevo ?", "va": "c"}, {"l": "Je vais parler à Matveï", "va": "d", "trace": "vu_matvei_5"}]}}, "debutSi": {"brouillon_donne": "r0", "se_dedit": "s1"}, "resumeRetour": "Vera n'a pas brûlé la plainte. Pour la punir, le voïévode rouvre l'affaire de Zverevo : qui ment ?", "resumeSi": {"brouillon_donne": "Vera n'a pas brûlé la plainte. Pour la punir, le voïévode rouvre l'affaire de Zverevo : qui ment ?", "se_dedit": "Tu t'es dédit : Zverevo paie de nouveau. Mais ses trappeurs ont entendu ton premier aveu, et le voïévode les juge ce soir. Qui ment ?"}}, "-6": {"t": "La plainte de Vera", "resume": "Le voïévode offre à Vera son sceau si elle brûle la plainte au tsar, marquée par chaque famille. Aide-la à choisir : la paix tout de suite, ou la seule chose vraie qui reste.", "absents": ["bogdan"], "debut": "a", "debutRetour": "r1", "noeuds": {"a": {"qui": "vera", "txt": "Vera : « Le voïévode Borislav Andreïevitch me confirme starosta, avec son sceau, si je brûle ma plainte au tsar. Plus d'inspecteur : je lèverai le tribut moi-même. Un tribut fixe, du grain garanti. Il promet de rayer Bogdan du convoi des mines. Mais cette plainte est la seule chose vraie que nous ayons écrite. »", "rep": [{"l": "Que veut Oustina ?", "va": "b"}, {"l": "Où est la plainte, en ce moment ?", "va": "c"}, {"l": "Une plainte, ça mène où ?", "va": "d"}]}, "b": {"qui": "oustina", "txt": "Oustina : « Mon mari est un voleur, soit. Mais le voïévode peut le rayer du convoi. Une plainte, c'est une enquête, et il partira aux mines au printemps. Le voïévode ment peut-être. C'est la seule promesse qu'on m'ait faite. »", "rep": [{"l": "Je comprends", "va": "e", "trace": "ecoute_oustina"}]}, "c": {"lieu": "camp", "txt": "La plainte est cousue dans le manteau de Vera, pendu au séchoir. Tu prends le manteau pour le lui porter au cercle. Sur le chemin, trois hommes de Gleb t'attendent. La plainte nomme Gleb : il la veut avant Vera.", "combat": "Les hommes de Gleb veulent arracher le manteau de Vera et la plainte cousue dedans.", "gagne": "e", "apres": "Tu tiens la plainte. Trois pages écrites par Ilya, et en bas vingt marques, une par famille de Kobor. Le nom de Gleb revient sept fois, celui du voïévode onze fois.", "trace": "plainte_sauvee"}, "d": {"qui": "matvei", "txt": "Matveï : « Une plainte fait venir un homme de la ville. Il y a quarante ans, il en est venu un : Semion. Il a trouvé nos peaux cachées. Il a dit qu'il écrirait au trésor. On a eu peur. Je l'ai enfermé au Coffre, une nuit. Le froid l'a pris. Brûle la plainte, petite. Personne ne viendra. »", "rep": [{"l": "Retourner voir Vera", "va": "e", "trace": "aveu_matvei"}]}, "e": {"qui": "vera", "final": true, "txt": "Au cercle de pierres, Vera a décousu la plainte de son manteau. Elle la tient au-dessus du feu. Vingt marques, dont la sienne. Le voïévode attend à dix pas. Vera : « Si je la brûle, Kobor mange, et la marque de chaque famille disparaît. Si je la garde, Kobor reste debout, et il aura faim. Dis-moi ce que je fais. »", "txtTrace": {"aveu_matvei": "Plus bas : « Matveï m'a parlé de Semion, à moi aussi. »", "ecoute_oustina": "Oustina se tient au bord du cercle.", "plainte_sauvee": "Tu lui as rapporté le manteau."}, "fin": [{"vers": -7, "l": "Brûle-la", "prix": "Gleb et Borislav ne seront jamais jugés. Vera reçoit le sceau. Bogdan est rayé du convoi, sur parole.", "epreuve": "combat", "resultat": "Le papier noircit en une seconde. Borislav serre la main de Vera, et le sol craque sous les pierres : le gel descend d'une coudée.", "trace": "plainte_brulee", "combat": "Des familles qui ont mis leur marque veulent empêcher qu'on brûle la plainte."}, {"vers": -5, "l": "Garde-la", "prix": "Vera refuse le sceau. Borislav exige ses présents : cent peaux de plus, pour lui.", "epreuve": "combat", "combat": "Les gardes du voïévode veulent prendre la plainte des mains de Vera.", "resultat": "Vera range la plainte contre sa poitrine. Borislav part sans saluer, et Kobor sait déjà où passeront ses cent peaux.", "trace": "plainte_gardee"}]}, "r1": {"qui": "vera", "txt": "Vera : « L'envoyé du tsar sait, pour Semion : il l'a vu dans la glace. Matveï est sous garde, devant la Pierre. Moi, j'ai toujours le sceau, et ma plainte est en cendres. L'envoyé me demande ce que Kobor cache encore. Je ne sais plus quoi lui dire. »", "rep": [{"l": "Parler à Matveï", "va": "r2"}, {"l": "Qui avait écrit la plainte ?", "va": "r3"}]}, "r2": {"qui": "matvei", "txt": "Matveï, entre deux gardes : « Semion avait trouvé nos peaux cachées. Comme Gleb aujourd'hui. Dis à l'envoyé que c'était un accident, un homme perdu dans le froid. Toi, il te croira : tu es étranger. Moi, je ne reverrai pas le dégel. »", "rep": [{"l": "Aller voir Ilya", "va": "r3"}, {"l": "Revenir à Vera", "va": "r4"}]}, "r3": {"qui": "ilya", "txt": "Ilya : « J'ai écrit la plainte pour Vera. J'en ai gardé le brouillon, avec les vingt marques. Personne ne le sait. Si l'envoyé le lit, Gleb et le voïévode sont nommés devant le tsar. Et moi, j'avoue que j'ai acheté le tribut. »", "rep": [{"l": "Revenir à Vera", "va": "r4", "trace": "brouillon_ilya"}]}, "r4": {"qui": "vera", "final": true, "txt": "Devant le Coffre ouvert, l'envoyé du tsar attend. Vera : « Il veut un mot de toi, l'étranger. Ilya a gardé le brouillon de la plainte. Si tu le montres, je perds le sceau, et Kobor devra répondre de tout, Semion compris. Si tu dis « accident », tout se referme. »", "txtTrace": {"brouillon_ilya": "Ilya se tient derrière elle, le brouillon plié dans sa manche."}, "fin": [{"vers": -7, "l": "Dire : un accident ancien", "prix": "Semion reste « mort de froid ». Matveï est libéré. Plus personne ne posera jamais la question.", "epreuve": "dialogue", "resultat": "L'envoyé écrit « mort de froid, par accident ». On remet Semion au froid du Coffre en attendant que la terre dégèle, et la porte regèle avant la nuit.", "trace": "semion_accident"}, {"vers": -5, "l": "Montrer le brouillon à l'envoyé", "prix": "Vera perd le sceau. La plainte renaît, et Kobor répondra aussi de Semion. Ilya et Matveï répondront de leurs fautes.", "epreuve": "combat", "combat": "Les hommes de Gleb veulent arracher le brouillon avant qu'il atteigne l'envoyé.", "resultat": "L'envoyé lit le brouillon et le rend à Vera : sans ordre, il ne peut rien emporter. Vera le coud dans son manteau pour le convoi du printemps, et le givre de la porte se met à goutter.", "trace": "brouillon_donne"}]}, "s1": {"qui": "vera", "txt": "Vera : « Le chef de Zverevo est au fort, par notre faute. Et le voïévode Borislav Andreïevitch revient vers moi : il m'offre encore son sceau si je brûle la plainte. Cette fois, il ajoute : « Sinon, je rouvre l'affaire du grain. » La plainte est toujours dans mon manteau. »", "rep": [{"l": "Que veut Oustina ?", "va": "b"}, {"l": "Où est le manteau ?", "va": "c"}, {"l": "Une plainte, ça mène où ?", "va": "d"}]}}, "debutSi": {"zverevo_condamne": "s1"}, "resumeRetour": "La porte est ouverte : l'envoyé du tsar a vu Semion. Dis-lui « accident », ou montre-lui le brouillon de la plainte.", "resumeSi": {"zverevo_condamne": "Le chef de Zverevo est au fort. Le voïévode offre encore son sceau à Vera si elle brûle la plainte, sinon il rouvre l'affaire du grain."}}, "-7": {"t": "Personne n'est venu", "resume": "Un envoyé du tsar cherche Semion, l'inspecteur disparu il y a quarante ans. Chaque famille a baisé la croix : personne n'est jamais venu. Toi seul peux ouvrir la porte.", "absents": ["bogdan"], "debut": "a", "noeuds": {"a": {"lieu": "pierre", "txt": "Kobor est le hameau le plus en règle de la taïga. Le tribut est complet, et personne n'a eu faim cet hiver. Personne ne parle fort non plus. Le givre ne fond plus, même à midi. Devant la Pierre d'éveil, les traces de Bogdan, laissées le jour où on l'a emmené au fort, sont toujours nettes. Le voïévode avait promis de le rayer du convoi. Bogdan n'est pas revenu.", "rep": [{"l": "Aller voir la starosta", "va": "b"}, {"l": "Aller droit au Coffre", "va": "c"}]}, "b": {"qui": "vera", "txt": "Vera : « Un envoyé du tsar est là. La veuve de l'inspecteur Semion est morte cet automne. Dans ses papiers, une lettre : « Je pars pour Kobor. » Chaque famille a baisé la croix devant l'envoyé : personne n'est jamais venu. Moi aussi. Tout est en règle. Tout. »", "txtTrace": {"plainte_brulee": "Elle frotte ses doigts, comme s'ils sentaient encore la fumée."}, "rep": [{"l": "Aller au Coffre", "va": "c"}]}, "c": {"qui": "matvei", "final": true, "txt": "Matveï, assis devant la porte givrée du Coffre : « Il ne manque que ton baiser sur la croix. Baise-la, et la glace garde tout, pour toujours. Ou bien ouvre. Mais si tu ouvres, ils me prendront, et tout ce que nous avons tenu tombera avec moi. »", "txtTrace": {"aveu_matvei": "« Tu sais ce qu'il y a derrière. Je te l'ai dit moi-même. »", "voisin_accuse": "« Le chef de Zverevo n'est jamais revenu du fort, lui non plus. »"}, "fin": [{"vers": -6, "l": "Ouvrir la porte du Coffre", "prix": "Matveï sera jugé. Kobor perd sa paix gelée.", "epreuve": "combat", "combat": "Les gardes du voïévode barrent la porte du Coffre pour que l'envoyé ne voie rien.", "resultat": "La porte cède. Dans la glace, un homme en manteau d'inspecteur, le visage net, comme endormi : l'envoyé se découvre, et le givre se met à goutter.", "trace": "porte_ouverte"}], "refus": "Jurer et partir : la glace garde tout"}, "s1": {"lieu": "pierre", "txt": "Kobor est le hameau le plus en règle de la taïga. Le givre ne fond plus, même à midi. Derrière la porte regelée du Coffre, Semion attend le dégel pour être enterré. L'envoyé a écrit « accident ». Il n'est pas reparti. Les traces de Bogdan sont toujours nettes devant la Pierre : la promesse du voïévode n'a rien valu.", "rep": [{"l": "Aller voir la starosta", "va": "s2"}]}, "s2": {"qui": "vera", "txt": "Vera : « L'envoyé ne demande plus si quelqu'un est venu. Il demande si quelqu'un a fermé la porte. Chaque famille a baisé la croix : personne. Moi aussi. Il ne manque que toi. Matveï t'attend au Coffre. »", "rep": [{"l": "Aller au Coffre", "va": "s3"}]}, "s3": {"qui": "matvei", "final": true, "txt": "Matveï, devant la porte regelée : « Cette fois, jure seulement qu'il est mort seul. Baise la croix, et Semion sera enterré au dégel sous le mot « accident ». Ou bien dis à l'envoyé qui a tourné la clé. Alors ils me prendront, et tout ce que nous avons tenu tombera avec moi. »", "fin": [{"vers": -6, "l": "Dire qui a fermé la porte", "prix": "Matveï sera jugé. Kobor perd sa paix gelée.", "epreuve": "dialogue", "resultat": "Tu dis le nom de Matveï devant l'envoyé. On rouvre la porte : Semion n'est plus un accident, et le givre se met à goutter.", "trace": "porte_ouverte"}], "refus": "Jurer et partir : la glace garde tout"}}, "debutSi": {"semion_accident": "s1"}, "resumeSi": {"semion_accident": "L'envoyé a écrit « accident », mais il demande qui a fermé la porte. Jure, ou nomme Matveï."}}}}};
/* le livre de Kobor raconte la nouvelle histoire ; les anciennes inscriptions (ancienne histoire) sont retirées en attendant leur réécriture */
if(typeof LIVRES!=="undefined")LIVRES.DON045={"titre": "Ce que la glace garde", "auteur": "Les notes d'un scribe du recensement, venu à Kobor avec l'inspecteur Gleb, l'hiver où le Coffre fut trouvé vide.", "pages": [{"t": "Le hameau et le tribut", "txt": "Kobor est un hameau de trappeurs, au bord de la rivière, sous les mélèzes. Chaque hiver, il doit au voïévode Borislav Andreïevitch quatre cents zibelines. Les peaux attendent le convoi dans le Coffre, une loge creusée dans le sol gelé, devant la Pierre d'éveil. Le vieux Matveï garde la porte depuis quarante ans. Le sol, là-bas, ne dégèle jamais tout à fait. On dit que le froid y garde tout : la viande, les peaux, et le reste."}, {"t": "Le Coffre vide", "txt": "Cet hiver, quand Gleb a ouvert le Coffre, il était vide. Quatre cents peaux, parties. Pourtant, Kobor a mangé tout l'hiver, alors que la chasse avait été mauvaise. Les greniers sont pleins. La barge d'Ilya, le marchand de grain du sud, était venue à l'automne ; la glace l'a prise au bord du camp avant qu'elle reparte. Je crois que Vera, la cheffe, a échangé le tribut contre le grain d'Ilya : quarante charges de traîneau. Sans ce grain, Kobor serait mort."}, {"t": "Le coupable volontaire", "txt": "Gleb veut un coupable avant le dégel, sinon tout le hameau paiera. Le lendemain, un trappeur, Bogdan, s'est présenté : « J'ai vendu les peaux. » On l'a emmené au fort, enchaîné ; au printemps, le convoi l'emmènera aux mines. Bogdan doit tout à Vera : elle a payé sa dette l'an passé. Je crois qu'il a porté les peaux, cette nuit-là. Je ne crois pas qu'il en ait touché le prix. Sa femme, Oustina, ne pleure pas. Elle sait qu'il ment pour quelqu'un."}, {"t": "Ce que je n'ai pas écrit", "txt": "Gleb prend une peau sur dix pour le trésor. Je l'ai vu en prendre deux. Il en veut à Vera : avec Ilya pour scribe, elle a fait une plainte au tsar contre le voïévode et contre lui, chaque famille y a mis sa marque, et elle partira avec le convoi du printemps. Hier, un reçu de grain, à la marque de Vera, était posé devant le Coffre, bien en vue. Je sais qui l'a posé. Ce matin, j'ai demandé à Matveï si un inspecteur était déjà venu ici. Il a dit : « Semion, il y a quarante ans. » Je lui ai demandé quand il était reparti. Il a"}], "fin": {"m5": "Le reste de la page est collé par le givre. On ne peut pas la tourner sans la déchirer.", "m2": "La phrase s'arrête là. L'encre a gelé dans la plume, et personne n'a fini.", "z": "La phrase s'arrête là. La page suivante est blanche.", "p2": "La page suivante est humide. On y lit seulement : « ...pas reparti. »", "p5": "La page suivante a pris l'eau du dégel. Une pousse verte sort de la reliure. Sous elle, on lit : « Il n'est jamais reparti. Il est en bas. »"}};
if(typeof INSCRIPTIONS!=="undefined")delete INSCRIPTIONS.DON045;
